import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.14','Bremsen, Ziff.')
F="Die EVU regeln die erforderlichen Ergänzungen zu dieser Vorschrift in den Betriebsvorschriften, insbesondere die Bedienung im Einzelfall; die technische Beschreibung der Bremseinrichtungen; die Vorschriften über deren Unterhalt; die Besonderheiten der Bremseinrichtungen historischer Fahrzeuge, insbesondere der einlösigen Bremse; die Besonderheiten der Bremseinrichtungen von Zahnradfahrzeugen. Im Sinne dieser Vorschrift sind Antriebsbremsen wie hydrodynamische Bremsen oder Wirbelstrombremsen den elektrischen Bremsen gleichgestellt. Der Einsatz von auf die Schienen wirkenden Wirbelstrombremsen ist nicht zulässig."
addm("1","Ergänzungen EVU","Was regeln die EVU gemäss § in den Betriebsvorschriften insbesondere (Mehrfachauswahl).",["Die Bedienung im Einzelfall","Die technische Beschreibung der Bremseinrichtungen","Die Vorschriften über deren Unterhalt","Die Besonderheiten der Bremseinrichtungen historischer Fahrzeuge","Die Besonderheiten der Bremseinrichtungen von Zahnradfahrzeugen"],["Die Höchstgeschwindigkeit auf Strecken","Die Fahrplangestaltung"],F)
add("1","Antriebsbremsen","Welchen Bremsen sind Antriebsbremsen wie hydrodynamische Bremsen oder Wirbelstrombremsen gemäss § gleichgestellt?","Den elektrischen Bremsen.",["Den Reibungsbremsen.","Den Schienenbremsen.","Den Federspeicherbremsen."],F)
add("1","Wirbelstrombremsen Schiene","Was gilt gemäss § für auf die Schienen wirkende Wirbelstrombremsen?","Ihr Einsatz ist nicht zulässig.",["Ihr Einsatz ist nur bei Nacht zulässig.","Ihr Einsatz ist nur im Gefälle zulässig.","Ihr Einsatz ist mit Bewilligung des EVU zulässig."],F)
F="Bei der Bedienung der Bremsen sind möglichst wenige, jedoch bewusst überlegte und vorausschauende Handlungen auszuführen. Die Kenntnisse der wesentlichen Vorgänge in den Bremsapparaten, die Beobachtung der Manometer und des Geschwindigkeitsmessers, das Gefühl für die herrschende Verzögerung sowie das richtige Abschätzen der Bremswirkung, der Entfernung und der Adhäsionsverhältnisse sind die Hauptbedingungen für eine einwandfreie Bremsbedienung."
add("2.1.1","Bremsbedienung Grundsatz","Wie sind die Handlungen bei der Bedienung der Bremsen gemäss § auszuführen?","Möglichst wenige, jedoch bewusst überlegte und vorausschauende Handlungen.",["Möglichst viele kleine Bremsstufen.","Rasch und ohne langes Überlegen.","Immer mit der Schnellbremsung."],F)
addm("2.1.1","Hauptbedingungen","Was sind gemäss § die Hauptbedingungen für eine einwandfreie Bremsbedienung (Mehrfachauswahl).",["Kenntnisse der wesentlichen Vorgänge in den Bremsapparaten","Beobachtung der Manometer und des Geschwindigkeitsmessers","Gefühl für die herrschende Verzögerung","Richtiges Abschätzen der Bremswirkung, der Entfernung und der Adhäsionsverhältnisse"],["Kenntnis des Fahrplans","Anzahl der Reisenden im Zug"],F)
add("2.1.2","Mehrere bediente Triebfahrzeuge","Von wo aus wird die automatische Bremse gemäss § grundsätzlich bedient?","Von der Spitzenlok aus.",["Von der letzten Lok aus.","Von jeder Lok einzeln.","Vom Steuerwagen aus."],"Die automatische Bremse wird grundsätzlich von der Spitzenlok aus bedient.")
F="Nach Möglichkeit ist immer die elektrische Bremse zu verwenden. Bei ungenügender Wirkung der elektrischen Bremse ist zusätzlich die automatische Bremse zu verwenden. Für alleinfahrende Triebfahrzeuge ist nach Möglichkeit die elektrische Bremse zu verwenden, zum Anhalten die Rangier- oder gegebenenfalls die automatische Bremse."
add("2.2.1","Bremse Züge","Welche Bremse ist bei Zügen gemäss § nach Möglichkeit immer zu verwenden?","Die elektrische Bremse.",["Die automatische Bremse.","Die Rangierbremse.","Die Feststellbremse."],F)
add("2.2.1","Ungenügende elektrische Bremse","Was ist gemäss § bei ungenügender Wirkung der elektrischen Bremse zusätzlich zu verwenden?","Die automatische Bremse.",["Die Rangierbremse.","Die Feststellbremse.","Die Schienenbremse."],F)
add("2.2.1","Alleinfahrende Triebfahrzeuge","Welche Bremse ist bei alleinfahrenden Triebfahrzeugen gemäss § zum Anhalten zu verwenden?","Die Rangier- oder gegebenenfalls die automatische Bremse.",["Nur die elektrische Bremse.","Die Feststellbremse.","Die Schienenbremse."],F)
F="Grundsätzlich ist die automatische Bremse zu verwenden. Die Rangierbremse allein darf angewendet werden für alleinfahrende Triebfahrzeuge; bei kleinen Wagengruppen; in den erlaubten Fällen wo die Anhängelast nicht mit der Luft gebremst werden muss. Die EVU regeln in den Betriebsvorschriften die Anwendung der elektrischen Bremse bei Rangierbewegungen."
add("2.2.2","Rangierbewegungen Bremse","Welche Bremse ist bei Rangierbewegungen gemäss § grundsätzlich zu verwenden?","Die automatische Bremse.",["Die Rangierbremse.","Die elektrische Bremse.","Die Feststellbremse."],F)
addm("2.2.2","Rangierbremse allein","In welchen Fällen darf die Rangierbremse allein gemäss § angewendet werden (Mehrfachauswahl).",["Für alleinfahrende Triebfahrzeuge","Bei kleinen Wagengruppen","In den erlaubten Fällen, wo die Anhängelast nicht mit der Luft gebremst werden muss"],["Bei Rangierbewegungen mit Reisenden","Bei Fahrten im Gefälle"],F)
add("2.2.2","Elektrische Bremse Rangieren","Wer regelt gemäss § die Anwendung der elektrischen Bremse bei Rangierbewegungen?","Die EVU in den Betriebsvorschriften.",["Die ISB.","Der LF.","Der FDL."],F)
F="Stillstehende und mit LF besetzte Triebfahrzeuge mit oder ohne Anhängelast sind in jedem Fall mit der Rangierbremse zu sichern. Fehlt diese oder ist deren Wirkung ungenügend, ist die automatische Bremse oder gegebenenfalls die Feststellbremse zu verwenden."
add("2.2.3","Stillstand besetzt","Womit sind stillstehende und mit LF besetzte Triebfahrzeuge gemäss § in jedem Fall zu sichern?","Mit der Rangierbremse.",["Mit der Feststellbremse.","Mit der elektrischen Bremse.","Mit Hemmschuhen."],F)
add("2.2.3","Rangierbremse fehlt","Was ist gemäss § zu verwenden, wenn die Rangierbremse fehlt oder ihre Wirkung ungenügend ist?","Die automatische Bremse oder gegebenenfalls die Feststellbremse.",["Die elektrische Bremse.","Nur die Schienenbremse.","Hemmschuhe allein."],F)
F="Abgestellte und nicht mit LF besetzte Triebfahrzeuge sind mit der Feststellbremse zu sichern. Die EVU regeln in den Betriebsvorschriften die Anwendung von Feststellbremsen, welche sich über die Hauptleitung lösen lassen."
add("2.2.4","Abgestellte Triebfahrzeuge","Womit sind abgestellte und nicht mit LF besetzte Triebfahrzeuge gemäss § zu sichern?","Mit der Feststellbremse.",["Mit der Rangierbremse.","Mit der automatischen Bremse.","Mit der elektrischen Bremse."],F)
F="Im Winterbetrieb sind bei der Bremsbedienung mindestens folgende Massnahmen erforderlich: Bei Temperaturen unter 0°C hat der LF unmittelbar nach Beginn der Fahrt das leichtgängige Rollen der Fahrzeuge zu prüfen. Nach dem Anhalten auf Bahnhöfen sind die Bremsen, wenn möglich sofort zu lösen. Bei eingepresstem Schnee oder Eis zwischen Bremssohle und Rad bzw. Bremsbelag und Bremsscheibe kann die Wirkung der Feststellbremse nachlassen! Die Fahrzeuge sind zusätzlich mit Hemmschuhen zu sichern. Bremsungen mit der Luftbremse sind frühzeitig einzuleiten, um die Reibungsflächen (Bremssohlen, Scheibenbremsen) von Schnee und Eis zu befreien. Die EVU regeln den Winterbetrieb in den Betriebsvorschriften."
addm("2.2.5","Winterbetrieb","Welche Massnahmen sind im Winterbetrieb bei der Bremsbedienung gemäss § mindestens erforderlich (Mehrfachauswahl).",["Bei Temperaturen unter 0°C unmittelbar nach Fahrtbeginn das leichtgängige Rollen der Fahrzeuge prüfen","Nach dem Anhalten auf Bahnhöfen die Bremsen wenn möglich sofort lösen","Bei eingepresstem Schnee oder Eis die Fahrzeuge zusätzlich mit Hemmschuhen sichern","Luftbremsungen frühzeitig einleiten, um die Reibungsflächen von Schnee und Eis zu befreien"],["Die Bremsen nach dem Anhalten angezogen lassen","Bremsungen möglichst spät einleiten"],F)
add("2.2.5","Temperaturgrenze","Bei welcher Temperatur hat der LF gemäss § unmittelbar nach Beginn der Fahrt das leichtgängige Rollen der Fahrzeuge zu prüfen?","Bei Temperaturen unter 0°C.",["Bei Temperaturen unter 5°C.","Bei Temperaturen unter -10°C.","Bei Temperaturen über 0°C."],F)
F="Mit der Bremsprobe wird festgestellt, ob die Luft in beiden Richtungen ungehindert durch die Hauptleitung strömen kann und keine Undichtheiten an den Bremsapparaten wahrnehmbar sind; nach einer Betriebsbremsung vom bedienten Führerstand aus die Bremsen an allen gebremsten Achsen fest anliegen und nach dem Lösen der Bremse von der gleichen Stelle aus ohne Betätigen von Auslöseventilen wieder vollständig gelöst sind."
addm("2.3.1","Zweck Bremsprobe","Was wird mit der Bremsprobe gemäss § festgestellt (Mehrfachauswahl).",["Ob die Luft in beiden Richtungen ungehindert durch die Hauptleitung strömen kann und keine Undichtheiten wahrnehmbar sind","Ob nach einer Betriebsbremsung die Bremsen an allen gebremsten Achsen fest anliegen","Ob die Bremsen nach dem Lösen ohne Betätigen von Auslöseventilen wieder vollständig gelöst sind"],["Ob die Bremssohlen abgenützt sind","Ob die Zugsammelschiene unter Spannung steht"],F)
F="Die Bremsprobe darf erst begonnen werden, wenn die Steuerventile und die zugehörigen Luftbehälter aller an die Hauptleitung angeschlossenen Fahrzeuge gefüllt bzw. die Bremsapparate evakuiert sind. Bei Druckluftbremsen muss zudem in den Hauptluftbehältern mindestens der Normaldruck vorhanden sein. Bei den Normalspur- und vielen Schmalspurbahnen beträgt dieser 5 bar, bei einigen Bahnen 4, 4,2 oder 4,5 bar."
add("2.3.2","Betriebsbereitschaft","Wann darf die Bremsprobe gemäss § erst begonnen werden?","Wenn die Steuerventile und Luftbehälter aller angeschlossenen Fahrzeuge gefüllt bzw. die Bremsapparate evakuiert sind.",["Sobald die Hauptleitung angeschlossen ist.","Sobald der LF im Führerstand ist.","Sobald der Kompressor läuft."],F)
add("2.3.2","Normaldruck","Wie hoch beträgt der Normaldruck in den Hauptluftbehältern bei den Normalspur- und vielen Schmalspurbahnen gemäss §?","5 bar.",["4 bar.","6 bar.","7 bar."],F)
F="Die Füllzeit der leeren Bremsapparate eines druckluftgebremsten Fahrzeugs beträgt je nach Bremssystem bei der Personenzugbremse ca. 2 Minuten und bei der Güterzugbremse ca. 2 bis 5 Minuten. Mit zunehmender Länge des Zuges vergrössert sich die Gesamtfüllzeit. Für das Evakuieren der Bremsapparate eines vakuumgebremsten Fahrzeugs gelten ungefähr die gleichen Werte wie bei der Güterzugbremse."
add("2.3.3","Füllzeit Personenzugbremse","Wie lange beträgt die Füllzeit der leeren Bremsapparate bei der Personenzugbremse gemäss § ca.?","Ca. 2 Minuten.",["Ca. 30 Sekunden.","Ca. 5 Minuten.","Ca. 10 Minuten."],F)
add("2.3.3","Füllzeit Güterzugbremse","Wie lange beträgt die Füllzeit der leeren Bremsapparate bei der Güterzugbremse gemäss § ca.?","Ca. 2 bis 5 Minuten.",["Ca. 30 Sekunden.","Ca. 10 bis 15 Minuten.","Ca. 1 Minute."],F)
F="Die Hauptleitung und die Bremsapparate müssen wie folgt auf Dichtigkeit geprüft werden: Automatische Druckluftbremse: Vor Beginn der Hauptbremsprobe oder bei Verdacht auf Undichtigkeiten: Bei unterbrochener Nachspeisung darf der Druckverlust in der Hauptleitung während einer Minute höchstens 0,3 bar betragen. Vor Beginn der Zusatz- oder der vereinfachten Bremsprobe: Bei kurz unterbrochener Nachspeisung darf am Hauptleitungsmanometer kein Druckverlust feststellbar sein. Vakuumbremse: Vor Beginn der Bremsprobe: Bei abgestellter Vakuumpumpe darf das Vakuum während 10 Sekunden nicht mehr als 4 cmHg absinken und nicht unter 45 cmHg fallen."
add("2.3.4","Dichtigkeit Hauptbremsprobe","Wie hoch darf der Druckverlust in der Hauptleitung vor Beginn der Hauptbremsprobe bei unterbrochener Nachspeisung während einer Minute gemäss § höchstens sein?","0,3 bar.",["0,1 bar.","0,5 bar.","1 bar."],F)
add("2.3.4","Dichtigkeit Zusatzbremsprobe","Was gilt gemäss § vor Beginn der Zusatz- oder der vereinfachten Bremsprobe bei kurz unterbrochener Nachspeisung?","Am Hauptleitungsmanometer darf kein Druckverlust feststellbar sein.",["Der Druckverlust darf höchstens 0,3 bar betragen.","Der Druckverlust darf höchstens 0,5 bar betragen.","Der Druckverlust darf höchstens 1 bar betragen."],F)
add("2.3.4","Dichtigkeit Vakuum","Wie weit darf das Vakuum bei abgestellter Vakuumpumpe gemäss § während 10 Sekunden absinken?","Nicht mehr als 4 cmHg und nicht unter 45 cmHg.",["Nicht mehr als 10 cmHg und nicht unter 30 cmHg.","Nicht mehr als 2 cmHg und nicht unter 52 cmHg.","Nicht mehr als 4 cmHg und nicht unter 20 cmHg."],F)
F="Bei der Inbetriebnahme der Triebfahrzeuge ist die Funktion deren Luftbremsen durch den LF wie folgt zu prüfen: Die Rangierbremse ist mittels Bremszylinder-Manometer (1 bar und anschliessend voller Druck) oder Meldeeinrichtung zu prüfen. Die automatische Bremse ist wie folgt zu prüfen: Mittels Bremszylinder-Manometer oder Meldeeinrichtung für Lokzüge mit einzeln bedienten Triebfahrzeugen und für Rangierbewegungen. Bei Druckluftbremsen ist der Hauptleitungsdruck um 0,5 bar zu senken, bzw. bei der Vakuumbremse auf 20 cmHg zu bringen. Anschliessend ist zu prüfen, ob die Bremszylinder Druckluft enthalten. Vom Boden aus oder am Manometer für geschleppte oder in Vielfachsteuerung verkehrende Triebfahrzeuge in den Fällen, wo eine Hauptbremsprobe vorgeschrieben ist. Nach jedem Führerstandwechsel sind die Rangier- und die automatische Bremse und nach dem Abhängen des Triebfahrzeugs die Rangierbremse mittels Bremszylinder-Manometer oder Meldeeinrichtung zu prüfen. Sind keine Bremszylinder-Manometer oder Meldeeinrichtung vorhanden, ist die Bremse in jedem Fall vom Boden aus zu prüfen. Nach der Funktionsprüfung ist die Wirkung der Bremse unmittelbar nach dem Ingangsetzen des Triebfahrzeugs zu prüfen."
add("2.3.5","Prüfung Rangierbremse","Wie ist die Rangierbremse bei der Inbetriebnahme von Triebfahrzeugen gemäss § zu prüfen?","Mittels Bremszylinder-Manometer (1 bar und anschliessend voller Druck) oder Meldeeinrichtung.",["Nur durch eine Probefahrt.","Nur vom Boden aus.","Mit einer Schnellbremsung."],F)
add("2.3.5","Prüfung automatische Bremse Druckluft","Um wie viel ist der Hauptleitungsdruck bei der Prüfung der automatischen Druckluftbremse von Triebfahrzeugen gemäss § zu senken?","Um 0,5 bar.",["Um 1 bar.","Um 1,5 bar.","Um 0,3 bar."],F)
add("2.3.5","Prüfung automatische Bremse Vakuum","Auf welchen Wert ist das Vakuum bei der Prüfung der automatischen Vakuumbremse von Triebfahrzeugen gemäss § zu bringen?","Auf 20 cmHg.",["Auf 42 cmHg.","Auf 52 cmHg.","Auf 45 cmHg."],F)
addm("2.3.5","Prüfung nach Wechsel","Was ist gemäss § mittels Bremszylinder-Manometer oder Meldeeinrichtung zu prüfen (Mehrfachauswahl).",["Nach jedem Führerstandwechsel die Rangierbremse und die automatische Bremse","Nach dem Abhängen des Triebfahrzeugs die Rangierbremse"],["Nach jedem Halt die Feststellbremse","Nach jeder Betriebsbremsung die Magnetschienenbremse"],F)
add("2.3.5","Keine Anzeige","Wie ist die Bremse gemäss § zu prüfen, wenn keine Bremszylinder-Manometer oder Meldeeinrichtung vorhanden sind?","In jedem Fall vom Boden aus.",["Vom Führerstand aus durch Gefühl.","Gar nicht.","Durch eine Probefahrt."],F)
F="Die Probe der automatischen Bremse muss mit einer Betriebsbremsung durchgeführt werden. Bei Druckluftbremsen ist dabei der Hauptleitungsdruck um 1 bar zu senken. Die Bremse ist nach Möglichkeit mit einem Hochdruckfüllstoss mit anschliessender Niederdrucküberladung zu lösen."
add("2.3.6","Bremsprobe Zug Bremsen","Um wie viel ist der Hauptleitungsdruck bei der Bremsprobe der automatischen Druckluftbremse bei Zügen gemäss § zu senken?","Um 1 bar.",["Um 0,5 bar.","Um 1,5 bar.","Um 2 bar."],F)
add("2.3.6","Bremsprobe Zug Lösen","Wie ist die Bremse bei der Bremsprobe gemäss § nach Möglichkeit zu lösen?","Mit einem Hochdruckfüllstoss mit anschliessender Niederdrucküberladung.",["Nur in Fahrstellung.","Mit dem Auslöseventil.","Mit dem Nothahn."],F)
F="Der LF hat die Wirkung der Luftbremse zu prüfen: unmittelbar nach der Abfahrt vom Ausgangs- oder Wendebahnhof; nach Veränderungen an der Zusammensetzung des Zuges; nach einem LF-Wechsel; vor der Einfahrt in ein starkes Gefälle; vor der Einfahrt in einen Kopfbahnhof; von Zeit zu Zeit nach der letzten Bremsung mit der automatischen Bremse bei Flugschnee oder bei grosser Kälte. Die Bremsprobe auf Wirkung hat mit einer Betriebsbremsung bei ausgeschalteter elektrischer Bremse und ausgelöster Luftbremse des Triebfahrzeugs zu erfolgen. Für spezifische Fahrzeugbedienungen oder für die Einhaltung allfälliger Anwendungsbedingungen von Bremskomponenten (z.B. Bremssohlen aus Verbundstoff) erlassen die EVU entsprechende Betriebsvorschriften."
addm("2.3.7","Bremsprobe Wirkung","Wann hat der LF die Wirkung der Luftbremse gemäss § zu prüfen (Mehrfachauswahl).",["Unmittelbar nach der Abfahrt vom Ausgangs- oder Wendebahnhof","Nach Veränderungen an der Zusammensetzung des Zuges","Nach einem LF-Wechsel","Vor der Einfahrt in ein starkes Gefälle","Vor der Einfahrt in einen Kopfbahnhof","Von Zeit zu Zeit bei Flugschnee oder grosser Kälte nach der letzten Bremsung mit der automatischen Bremse"],["Nach jeder Durchfahrt durch einen Tunnel","Vor jeder Brücke"],F)
add("2.3.7","Durchführung Wirkung","Wie hat die Bremsprobe auf Wirkung gemäss § zu erfolgen?","Mit einer Betriebsbremsung bei ausgeschalteter elektrischer Bremse und ausgelöster Luftbremse des Triebfahrzeugs.",["Mit einer Schnellbremsung.","Mit eingeschalteter elektrischer Bremse.","Mit einer Vollbremsung."],F)
add("2.3.8","Sicherheitsbremse Bremsprobe","Wer regelt gemäss § die Durchführung der Bremsprobe der Sicherheitsbremse?","Die EVU in den Betriebsvorschriften.",["Die ISB.","Das BAV.","Der LF."],"Die EVU regeln die Durchführung der Bremsprobe der Sicherheitsbremse in den Betriebsvorschriften.")
F="Es wird zwischen folgenden Bremsbedienungsarten unterschieden: Betriebsbremsung, Vollbremsung, Schnellbremsung, Notbremsung, Zwangsbremsung."
addm("2.4.1","Bremsbedienungsarten","Welche Bremsbedienungsarten der automatischen Druckluftbremse werden gemäss § unterschieden (Mehrfachauswahl).",["Betriebsbremsung","Vollbremsung","Schnellbremsung","Notbremsung","Zwangsbremsung"],["Teilbremsung","Dauerbremsung","Sicherheitsbremsung"],F)
F="Die Betriebsbremsung wird zum Anhalten der Züge und für Geschwindigkeitsreduktionen angewendet. Der Druck in der Hauptleitung wird stufenweise oder auf einmal um weniger als 1,5 bar reduziert. Die erste Druckabsenkung soll dabei rasch erfolgen. Sie soll für Züge mit Gusssohlen mindestens 0,4 bis 0,5 bar, für Reisezüge mit Scheibenbremsen oder Verbundstoffsohlen mindestens 0,5 bis 0,8 bar und für Güterzüge mit Scheibenbremsen oder Verbundstoffsohlen mindestens 1 bar betragen."
add("2.4.1","Betriebsbremsung Zweck","Wofür wird die Betriebsbremsung gemäss § angewendet?","Zum Anhalten der Züge und für Geschwindigkeitsreduktionen.",["Nur zum Anhalten bei Gefahr.","Nur im Gefälle.","Nur zum Sichern abgestellter Züge."],F)
add("2.4.1","Betriebsbremsung Druck","Um wie viel wird der Druck in der Hauptleitung bei einer Betriebsbremsung gemäss § reduziert?","Stufenweise oder auf einmal um weniger als 1,5 bar.",["Um genau 1,5 bar.","Um mindestens 1,5 bar.","Auf 0 bar."],F)
add("2.4.1","Erste Druckabsenkung","Wie soll die erste Druckabsenkung bei einer Betriebsbremsung gemäss § erfolgen?","Rasch.",["Langsam.","In kleinen Stufen von 0,1 bar.","Erst nach Erreichen der Höchstgeschwindigkeit."],F)
add("2.4.1","Erste Absenkung Gusssohlen","Wie gross soll die erste Druckabsenkung bei Zügen mit Gusssohlen gemäss § mindestens sein?","0,4 bis 0,5 bar.",["0,5 bis 0,8 bar.","1 bar.","1,5 bar."],F)
add("2.4.1","Erste Absenkung Reisezüge","Wie gross soll die erste Druckabsenkung bei Reisezügen mit Scheibenbremsen oder Verbundstoffsohlen gemäss § mindestens sein?","0,5 bis 0,8 bar.",["0,4 bis 0,5 bar.","1 bar.","1,5 bar."],F)
add("2.4.1","Erste Absenkung Güterzüge","Wie gross soll die erste Druckabsenkung bei Güterzügen mit Scheibenbremsen oder Verbundstoffsohlen gemäss § mindestens sein?","1 bar.",["0,4 bar.","0,5 bis 0,8 bar.","1,5 bar."],F)
F="Eine Vollbremsung liegt vor, wenn der Druck in der Hauptleitung um 1,5 bar vermindert wird. Dadurch wird der grösste mögliche Bremszylinderdruck und somit auch die grösste Bremskraft der automatischen Bremse erreicht."
add("2.4.1","Vollbremsung Definition","Wann liegt gemäss § eine Vollbremsung vor?","Wenn der Druck in der Hauptleitung um 1,5 bar vermindert wird.",["Wenn die Hauptleitung vollständig entleert wird.","Wenn der Druck um 1 bar vermindert wird.","Wenn der Druck um weniger als 1,5 bar vermindert wird."],F)
add("2.4.1","Vollbremsung Wirkung","Was wird bei einer Vollbremsung gemäss § erreicht?","Der grösste mögliche Bremszylinderdruck und somit die grösste Bremskraft der automatischen Bremse.",["Der kürzeste Bremsweg durch Magnetschienenbremsen.","Ein Bremszylinderdruck von 0 bar.","Ein stufenweises Lösen der Bremse."],F)
F="Eine Schnellbremsung liegt vor, wenn die Hauptleitung mit dem Führerbremsventil über einen grossen Auslassquerschnitt vollständig entleert wird (0 bar). Durch das rasche und vollständige Entleeren der Hauptleitung wird in kürzester Zeit bei gleicher Bremskraft wie bei einer Vollbremsung der kürzeste Bremsweg erreicht. Zudem wirken bei entsprechend ausgerüsteten Fahrzeugen die Magnetschienenbremsen, die Schnellbremsbeschleunigungsventile und, sofern geschleppt, bei Triebfahrzeugen die Nachbremse. Bei Triebfahrzeugen wirkt eine vorher ausgelöste Luftbremse wieder voll."
add("2.4.1","Schnellbremsung Definition","Wann liegt gemäss § eine Schnellbremsung vor?","Wenn die Hauptleitung mit dem Führerbremsventil über einen grossen Auslassquerschnitt vollständig entleert wird (0 bar).",["Wenn der Druck in der Hauptleitung um 1,5 bar vermindert wird.","Wenn eine Sicherheitseinrichtung die Hauptleitung entleert.","Wenn der Notbremsgriff betätigt wird."],F)
add("2.4.1","Schnellbremsung Bremsweg","Wie verhält sich die Bremskraft bei einer Schnellbremsung im Vergleich zur Vollbremsung gemäss §?","Sie ist gleich gross, der Bremsweg ist jedoch am kürzesten.",["Sie ist grösser, der Bremsweg ist gleich lang.","Sie ist kleiner, der Bremsweg ist kürzer.","Sie ist gleich gross und der Bremsweg ist gleich lang."],F)
addm("2.4.1","Schnellbremsung zusätzlich","Was wirkt bei einer Schnellbremsung gemäss § bei entsprechend ausgerüsteten Fahrzeugen zusätzlich (Mehrfachauswahl).",["Die Magnetschienenbremsen","Die Schnellbremsbeschleunigungsventile","Bei geschleppten Triebfahrzeugen die Nachbremse"],["Die Hemmschuhe","Die Federspeicherbremsen"],F)
add("2.4.1","Schnellbremsung Triebfahrzeug","Was geschieht gemäss § bei Triebfahrzeugen mit einer vorher ausgelösten Luftbremse bei einer Schnellbremsung?","Die Luftbremse wirkt wieder voll.",["Die Luftbremse bleibt ausgelöst.","Die Luftbremse wirkt nur zur Hälfte.","Die elektrische Bremse wird abgeschaltet."],F)
add("2.4.1","Notbremsung Definition","Wann liegt gemäss § bei der automatischen Druckluftbremse eine Notbremsung vor?","Wenn durch das Betätigen einer Notbremseinrichtung die Hauptleitung entleert wird.",["Wenn der Druck in der Hauptleitung um 1,5 bar vermindert wird.","Wenn der Fahrzeugrechner die Hauptleitung entleert.","Wenn der LF das Führerbremsventil in die Fahrstellung bringt."],"Eine Notbremsung liegt vor, wenn durch das Betätigen einer Notbremseinrichtung die Hauptleitung entleert wird. Die Wirkung ist grundsätzlich dieselbe wie bei einer Schnellbremsung.")
F="Eine Zwangsbremsung liegt vor, wenn durch eine Sicherheitseinrichtung oder durch den Fahrzeugrechner die Hauptleitung entleert wird. Die Wirkung ist grundsätzlich dieselbe wie bei einer Schnellbremsung. Sofern zusätzlich die Nachspeisung unterbrochen wird, verkürzt sich die Zeit für den Aufbau der maximalen Bremskraft entsprechend."
add("2.4.1","Zwangsbremsung Definition","Wann liegt gemäss § bei der automatischen Druckluftbremse eine Zwangsbremsung vor?","Wenn durch eine Sicherheitseinrichtung oder durch den Fahrzeugrechner die Hauptleitung entleert wird.",["Wenn durch das Betätigen einer Notbremseinrichtung die Hauptleitung entleert wird.","Wenn der LF eine Vollbremsung einleitet.","Wenn der Druck in der Hauptleitung um weniger als 1,5 bar sinkt."],F)
add("2.4.1","Zwangsbremsung Nachspeisung","Was bewirkt gemäss § eine zusätzlich unterbrochene Nachspeisung bei einer Zwangsbremsung?","Die Zeit für den Aufbau der maximalen Bremskraft verkürzt sich.",["Die Bremse löst nach kurzer Zeit.","Die Bremskraft wird verringert.","Die Zeit für den Aufbau der maximalen Bremskraft verlängert sich."],F)
F="Das Führerbremsventil ist zum Lösen bzw. Füllen der Bremsen in die Fahrstellung, bzw. wenn vorhanden, in die Füllstellung (Querschnittswechsel) zu verbringen. Dabei ist die Funktion einer Niederdrucküberladung (Angleichfunktion), sofern vorhanden, anzuwenden. Bei Führerbremsventilen ohne zeitliche Begrenzung des Füllstosses ist beim Verbringen in die Füllstellung darauf zu achten, dass bei vollständig gelöster Bremse der Normaldruck in der Hauptleitung höchstens um 0,4 bar überschritten wird."
add("2.4.2","Lösen Stellung","In welche Stellung ist das Führerbremsventil gemäss § zum Lösen bzw. Füllen der Bremsen zu verbringen?","In die Fahrstellung, bzw. wenn vorhanden, in die Füllstellung.",["In die Betriebsbremsstellung.","In die Abschlussstellung.","In die Schnellbremsstellung."],F)
add("2.4.2","Überschreitung Normaldruck","Um wie viel darf der Normaldruck in der Hauptleitung bei Führerbremsventilen ohne zeitliche Begrenzung des Füllstosses bei vollständig gelöster Bremse gemäss § höchstens überschritten werden?","Um 0,4 bar.",["Um 0,1 bar.","Um 1 bar.","Um 1,5 bar."],F)
F="Das Lösen mit Füllstellung ist in der Regel anzuwenden: nach dem Ankuppeln des Triebfahrzeugs an den Zug; bei der Inbetriebnahme eines Pendelzugs; wenn unterwegs Wagen beigestellt werden; bei der Bremsprobe; zum sicheren Lösen der Bremsen während der Fahrt, ausgenommen bei Zügen bis zu einer Gesamtlänge von 125 m; wenn vorher aus der Niederdrucküberladung gebremst werden musste; am Ende einer Gefällefahrt."
addm("2.4.2","Lösen mit Füllstellung 1","In welchen Fällen ist das Lösen mit Füllstellung gemäss § in der Regel anzuwenden (Mehrfachauswahl).",["Nach dem Ankuppeln des Triebfahrzeugs an den Zug","Bei der Inbetriebnahme eines Pendelzugs","Wenn unterwegs Wagen beigestellt werden","Bei der Bremsprobe"],["Bei der Anwendung der Sägezahnmethode","Wenn kurze Zeit nach dem Lösen wieder gebremst werden muss"],F)
addm("2.4.2","Lösen mit Füllstellung 2","In welchen weiteren Fällen ist das Lösen mit Füllstellung gemäss § in der Regel anzuwenden (Mehrfachauswahl).",["Zum sicheren Lösen der Bremsen während der Fahrt, ausgenommen bei Zügen bis zu einer Gesamtlänge von 125 m","Wenn vorher aus der Niederdrucküberladung gebremst werden musste","Am Ende einer Gefällefahrt"],["Bei jedem Lösen der Bremsen im Bahnhof","Bei Zügen bis zu einer Gesamtlänge von 125 m während der Fahrt"],F)
add("2.4.2","Zuglänge Füllstellung","Bei Zügen bis zu welcher Gesamtlänge ist das Lösen mit Füllstellung zum sicheren Lösen der Bremsen während der Fahrt gemäss § in der Regel nicht anzuwenden?","Bis zu einer Gesamtlänge von 125 m.",["Bis zu 50 m.","Bis zu 250 m.","Bis zu 400 m."],F)
F="Das Lösen in Füllstellung bzw. der Aufbau einer Niederdrucküberladung ist zu vermeiden: wenn kurze Zeit nach dem Lösen wieder gebremst werden muss; bei der Anwendung der Sägezahnmethode; wenn die Bremsen kurz danach mit einem andern Führerbremsventil bedient werden. Bei gelöster Bremse ist das Verbringen des Führerbremsventils in die Füllstellung bzw. der Aufbau einer Niederdrucküberladung zu unterlassen."
addm("2.4.2","Füllstellung vermeiden","In welchen Fällen ist das Lösen in Füllstellung bzw. der Aufbau einer Niederdrucküberladung gemäss § zu vermeiden (Mehrfachauswahl).",["Wenn kurze Zeit nach dem Lösen wieder gebremst werden muss","Bei der Anwendung der Sägezahnmethode","Wenn die Bremsen kurz danach mit einem andern Führerbremsventil bedient werden"],["Nach dem Ankuppeln des Triebfahrzeugs an den Zug","Bei der Bremsprobe"],F)
add("2.4.2","Gelöste Bremse Füllstellung","Was ist gemäss § bei gelöster Bremse zu unterlassen?","Das Verbringen des Führerbremsventils in die Füllstellung bzw. der Aufbau einer Niederdrucküberladung.",["Das Verbringen des Führerbremsventils in die Fahrstellung.","Das Betätigen der elektrischen Bremse.","Das Beobachten des Hauptleitungsmanometers."],F)
F="Die Betriebsbremsung wird zum Anhalten der Züge und für Geschwindigkeitsreduktionen angewendet. Das Vakuum in der Hauptleitung wird stufenweise oder auf einmal auf 42 bis 20 cmHg abgesenkt."
add("2.5.1","Vakuum Betriebsbremsung","Auf welchen Wert wird das Vakuum in der Hauptleitung bei einer Betriebsbremsung der Vakuumbremse gemäss § abgesenkt?","Stufenweise oder auf einmal auf 42 bis 20 cmHg.",["Auf 52 bis 45 cmHg.","Auf 20 bis 0 cmHg.","Vollständig auf 0 cmHg."],F)
add("2.5.1","Vakuum Vollbremsung","Wann liegt gemäss § bei der Vakuumbremse eine Vollbremsung vor?","Wenn das Vakuum in der Hauptleitung mit dem Führerbremsventil vollständig aufgehoben wird.",["Wenn das Vakuum auf 42 bis 20 cmHg abgesenkt wird.","Wenn das Vakuum über einen grossen Einlassquerschnitt augenblicklich aufgehoben wird.","Wenn ein Notbremshahn geöffnet wird."],"Eine Vollbremsung liegt vor, wenn das Vakuum in der Hauptleitung mit dem Führerbremsventil vollständig aufgehoben wird.")
F="Eine Schnellbremsung liegt vor, wenn das Vakuum in der Hauptleitung mit dem Führerbremsventil über einen grossen Einlassquerschnitt augenblicklich aufgehoben wird. Die dadurch ausgelöste Druckwelle bewirkt, dass in rascher Folge alle Schnellbremsventile ansprechen. Damit wird in kürzester Zeit bei grösster Bremskraft der kürzeste Bremsweg erreicht."
add("2.5.1","Vakuum Schnellbremsung","Wann liegt gemäss § bei der Vakuumbremse eine Schnellbremsung vor?","Wenn das Vakuum mit dem Führerbremsventil über einen grossen Einlassquerschnitt augenblicklich aufgehoben wird.",["Wenn das Vakuum stufenweise auf 20 cmHg abgesenkt wird.","Wenn das Vakuum durch ein Notbremshahn zerstört wird.","Wenn die Vakuumpumpe abgestellt wird."],F)
add("2.5.1","Vakuum Druckwelle","Was bewirkt die bei einer Schnellbremsung der Vakuumbremse ausgelöste Druckwelle gemäss §?","Dass in rascher Folge alle Schnellbremsventile ansprechen.",["Dass die Vakuumpumpe abgestellt wird.","Dass die Bremsen gelöst werden.","Dass die Zwangsbremsung unterbrochen wird."],F)
add("2.5.1","Vakuum Notbremsung","Wann liegt gemäss § bei der Vakuumbremse eine Notbremsung vor?","Wenn das Vakuum durch das Öffnen eines Notbremshahns vollständig zerstört wird.",["Wenn das Vakuum auf 42 cmHg abgesenkt wird.","Wenn das Vakuum durch eine Sicherheitseinrichtung zerstört wird.","Wenn die Vakuumpumpe ausfällt."],"Eine Notbremsung liegt vor, wenn das Vakuum in der Hauptleitung durch das Öffnen eines Notbremshahns vollständig zerstört wird. Die Wirkung ist grundsätzlich dieselbe wie bei einer Schnellbremsung.")
add("2.5.1","Vakuum Zwangsbremsung","Wann liegt gemäss § bei der Vakuumbremse eine Zwangsbremsung vor?","Wenn das Vakuum durch eine Sicherheitseinrichtung oder durch den Fahrzeugrechner vollständig zerstört wird.",["Wenn das Vakuum durch das Öffnen eines Notbremshahns zerstört wird.","Wenn das Vakuum auf 20 cmHg abgesenkt wird.","Wenn der LF das Vakuum stufenweise absenkt."],"Eine Zwangsbremsung liegt vor, wenn das Vakuum durch eine Sicherheitseinrichtung oder durch den Fahrzeugrechner vollständig zerstört wird.")
F="Die Vakuumpumpe ist während der Fahrt mit der niedrigsten Drehzahl zu betreiben. Für das Evakuieren der Bremsapparate nach der Zugbildung und für das rasche Lösen bei der Bremsprobe ist eine höhere Drehzahl zu wählen."
add("2.5.2","Vakuumpumpe Fahrt","Mit welcher Drehzahl ist die Vakuumpumpe während der Fahrt gemäss § zu betreiben?","Mit der niedrigsten Drehzahl.",["Mit der höchsten Drehzahl.","Mit mittlerer Drehzahl.","Sie ist abzustellen."],F)
add("2.5.2","Vakuumpumpe Evakuieren","Welche Drehzahl ist für das Evakuieren der Bremsapparate nach der Zugbildung gemäss § zu wählen?","Eine höhere Drehzahl.",["Die niedrigste Drehzahl.","Die Pumpe ist abzustellen.","Die Drehzahl ist egal."],F)
F="Die elektrische Bremse muss für Gefällefahrten, Geschwindigkeitsverminderungen und zum Anhalten immer mit der zulässigen Bremskraft verwendet werden. Die elektrische Bremse soll frühzeitig in Betrieb genommen werden. Bei einem Versagen derselben muss noch genügend Zeit verbleiben, um an deren Stelle die Luftbremse anzuwenden."
add("2.6.1","Elektrische Bremse Kraft","Mit welcher Bremskraft muss die elektrische Bremse für Gefällefahrten, Geschwindigkeitsverminderungen und zum Anhalten gemäss § verwendet werden?","Immer mit der zulässigen Bremskraft.",["Nur mit stark verminderter Bremskraft.","Nur mit halber Bremskraft.","Nur im Notfall mit voller Bremskraft."],F)
add("2.6.1","Elektrische Bremse früh","Warum soll die elektrische Bremse gemäss § frühzeitig in Betrieb genommen werden?","Damit bei einem Versagen noch genügend Zeit verbleibt, um an deren Stelle die Luftbremse anzuwenden.",["Damit die Fahrleitung entlastet wird.","Damit die Bremssohlen geschont werden.","Damit die Zugsammelschiene nicht überlastet wird."],F)
F="Sofern Langsamfahrstellen oder Weichen in ablenkender Stellung mit höchstens 40 km/h befahren werden können, darf die elektrische Bremse der Triebfahrzeuge an der Spitze von Zügen und Rangierbewegungen nur mit stark verminderter Bremskraft verwendet werden. Befinden sich mehrere Triebfahrzeuge mit elektrischer Bremse an der Zugspitze, gelten folgende Einschränkungen: Bei einzeln bedienten Triebfahrzeugen darf nur auf dem an der Spitze und den schiebenden Triebfahrzeugen die höchstzulässige Bremskraft ausgenützt werden. Bei allen übrigen Triebfahrzeugen darf mit der elektrischen Bremse nur deren Eigengewicht abgebremst werden. Bei Triebfahrzeugen in Vielfachsteuerung darf nur mit reduzierter Bremskraft gemäss den Vorgaben des EVU gebremst werden."
add("2.6.2","Elektrische Bremse Langsamfahrstellen","Wie darf die elektrische Bremse der Triebfahrzeuge an der Spitze gemäss § verwendet werden, wenn Langsamfahrstellen oder Weichen in ablenkender Stellung mit höchstens 40 km/h befahren werden können?","Nur mit stark verminderter Bremskraft.",["Mit der zulässigen Bremskraft.","Gar nicht.","Nur mit halber Bremskraft."],F)
add("2.6.2","Einzeln bediente Triebfahrzeuge","Auf welchen einzeln bedienten Triebfahrzeugen darf gemäss § die höchstzulässige Bremskraft der elektrischen Bremse ausgenützt werden?","Nur auf dem an der Spitze und den schiebenden Triebfahrzeugen.",["Auf allen Triebfahrzeugen.","Nur auf den schiebenden Triebfahrzeugen.","Nur auf dem Triebfahrzeug am Zugschluss."],F)
add("2.6.2","Übrige Triebfahrzeuge","Was darf bei den übrigen einzeln bedienten Triebfahrzeugen gemäss § mit der elektrischen Bremse abgebremst werden?","Nur deren Eigengewicht.",["Die gesamte Anhängelast.","Die Hälfte der Anhängelast.","Das Eigengewicht und die Anhängelast."],F)
add("2.6.2","Vielfachsteuerung elektrische Bremse","Wie darf bei Triebfahrzeugen in Vielfachsteuerung gemäss § mit der elektrischen Bremse gebremst werden?","Nur mit reduzierter Bremskraft gemäss den Vorgaben des EVU.",["Mit der höchstzulässigen Bremskraft.","Gar nicht.","Mit der Bremskraft gemäss Weisung des FDL."],F)
F="Bei der Fahrt über Weichen in ablenkender Stellung, die höchstens mit 40 km/h befahren werden dürfen, ist folgendes zu beachten: Zum Vermindern der Geschwindigkeit oder zum Anhalten soll der Hauptleitungsdruck höchstens um 0,5 bar gesenkt werden, ausgenommen wenn Gefahr droht. Wenn beim Anhalten der Druck in der Hauptleitung um mehr als 1 bar gesenkt wurde, ist vor der Weiterfahrt der ganze Zug bzw. die Rangierbewegung bei gelöster automatischer Bremse vor Ort auf Unregelmässigkeiten zu kontrollieren."
add("2.7.1","Weichen 40 km/h Absenkung","Um wie viel soll der Hauptleitungsdruck bei der Fahrt über Weichen in ablenkender Stellung (höchstens 40 km/h) gemäss § zum Vermindern der Geschwindigkeit oder zum Anhalten höchstens gesenkt werden?","Um 0,5 bar.",["Um 0,3 bar.","Um 1 bar.","Um 1,5 bar."],F)
add("2.7.1","Weichen Kontrolle","Wann ist gemäss § vor der Weiterfahrt der ganze Zug bzw. die Rangierbewegung bei gelöster automatischer Bremse vor Ort zu kontrollieren?","Wenn beim Anhalten der Druck in der Hauptleitung um mehr als 1 bar gesenkt wurde.",["Wenn der Druck um mehr als 0,5 bar gesenkt wurde.","Wenn der Druck um 1,5 bar gesenkt wurde.","Nach jedem Halt auf einer Weiche."],F)
F="Sobald bei Gefällefahrten mit einer zulässigen Höchstgeschwindigkeit von > 40 km/h die elektrische Bremse des Triebfahrzeugs allein zum Einhalten der Geschwindigkeit nicht mehr genügt, muss die Sägezahnmethode angewendet werden. Dadurch wird eine thermische Überbeanspruchung von Rädern, Bremsscheiben und Bremsklötzen vermieden und das Risiko, dass sich die Bremsen auf der Gefällefahrt erschöpfen ist ausgeschlossen. Mit einer genügend starken Bremsung (Hauptleitungsdruck auf 4,6 bis 4 bar senken) ist die Geschwindigkeit so weit abzusenken, dass zwischen dem Lösen und dem Einleiten der neuen Bremsung eine Zeit von mindestens 90 Sekunden verbleibt. Die zur Geschwindigkeitsreduktion benötigte Bremszeit sollte dabei 60 Sekunden nicht überschreiten. Zum anschliessenden Lösen ist nur die Fahrstellung des Führerbremsventils zu verwenden. Das Zeitintervall von mindestens 90 Sekunden bis zum Einleiten der nächsten Bremsung ist zu überprüfen. Nötigenfalls ist die Geschwindigkeitsreduktion anzupassen. Die Luftbremse der Triebfahrzeuge ist nach Möglichkeit auszulösen."
add("2.7.2","Sägezahn Anwendung","Wann muss bei Gefällefahrten von Normalspurzügen gemäss § die Sägezahnmethode angewendet werden?","Sobald bei einer zulässigen Höchstgeschwindigkeit von > 40 km/h die elektrische Bremse allein zum Einhalten der Geschwindigkeit nicht mehr genügt.",["Bei Triebfahrzeugen ohne elektrische Bremse.","Bei jeder Gefällefahrt.","Bei Gefällefahrten mit einer zulässigen Höchstgeschwindigkeit von höchstens 40 km/h."],F)
add("2.7.2","Sägezahn Zweck","Was wird durch die Sägezahnmethode gemäss § vermieden?","Eine thermische Überbeanspruchung von Rädern, Bremsscheiben und Bremsklötzen sowie das Erschöpfen der Bremsen.",["Ein Überladen der Hauptleitung.","Ein Einfrieren der Bremssohlen.","Ein Ansprechen der Zwangsbremsung."],F)
add("2.7.2","Sägezahn Hauptleitungsdruck","Auf welchen Wert ist der Hauptleitungsdruck bei der Sägezahnmethode gemäss § mit einer genügend starken Bremsung zu senken?","Auf 4,6 bis 4 bar.",["Auf 4,8 bis 4,6 bar.","Auf 4,6 bis 4,4 bar.","Auf 3,5 bis 3 bar."],F)
add("2.7.2","Sägezahn Intervall","Wie lange muss bei der Sägezahnmethode zwischen dem Lösen und dem Einleiten der neuen Bremsung gemäss § mindestens verbleiben?","90 Sekunden.",["30 Sekunden.","60 Sekunden.","120 Sekunden."],F)
add("2.7.2","Sägezahn Bremszeit","Wie lange sollte die zur Geschwindigkeitsreduktion benötigte Bremszeit bei der Sägezahnmethode gemäss § höchstens betragen?","60 Sekunden.",["30 Sekunden.","90 Sekunden.","120 Sekunden."],F)
add("2.7.2","Sägezahn Lösen","Welche Stellung des Führerbremsventils ist bei der Sägezahnmethode gemäss § zum Lösen zu verwenden?","Nur die Fahrstellung.",["Die Füllstellung.","Die Schnellbremsstellung.","Die Abschlussstellung."],F)
add("2.7.2","Sägezahn Luftbremse Triebfahrzeug","Was gilt gemäss § bei der Sägezahnmethode für die Luftbremse der Triebfahrzeuge?","Sie ist nach Möglichkeit auszulösen.",["Sie soll nicht ausgelöst werden.","Sie ist zwingend angezogen zu lassen.","Sie ist abzuschalten."],F)
F="Bei Zügen mit Triebfahrzeugen ohne oder mit gestörter elektrischer Bremse muss bei der Gefällefahrt die Reguliermethode angewendet werden. Dabei ist zum Einhalten der Geschwindigkeit der Hauptleitungsdruck zwischen 4,6 bis 4,4 bar zu regulieren. Das Fahren mit einem Hauptleitungsdruck zu nahe an der Lösegrenze von 4,8 bar ist zu vermeiden. Die Luftbremse der Triebfahrzeuge soll nicht ausgelöst werden. Nötigenfalls regeln die EVU in den Betriebsvorschriften eine Verminderung der Höchstgeschwindigkeit."
add("2.7.2","Reguliermethode Anwendung","Wann muss bei der Gefällefahrt gemäss § die Reguliermethode angewendet werden?","Bei Zügen mit Triebfahrzeugen ohne oder mit gestörter elektrischer Bremse.",["Bei Zügen mit funktionierender elektrischer Bremse.","Bei jeder Gefällefahrt über 40 km/h.","Nur bei Güterzügen über 1200 t."],F)
add("2.7.2","Reguliermethode Hauptleitungsdruck","Zwischen welchen Werten ist der Hauptleitungsdruck bei der Reguliermethode gemäss § zu regulieren?","Zwischen 4,6 und 4,4 bar.",["Zwischen 4,8 und 4,6 bar.","Zwischen 4,6 und 4 bar.","Zwischen 5 und 4,8 bar."],F)
add("2.7.2","Lösegrenze","Wie hoch liegt die Lösegrenze des Hauptleitungsdrucks, der bei der Reguliermethode gemäss § nicht zu nahe befahren werden soll?","4,8 bar.",["4,4 bar.","4,6 bar.","5 bar."],F)
add("2.7.2","Reguliermethode Luftbremse Triebfahrzeug","Was gilt gemäss § bei der Reguliermethode für die Luftbremse der Triebfahrzeuge?","Sie soll nicht ausgelöst werden.",["Sie ist nach Möglichkeit auszulösen.","Sie ist abzuschalten.","Sie ist nur auf dem letzten Triebfahrzeug zu lösen."],F)
add("2.7.2","Reguliermethode Höchstgeschwindigkeit","Wer regelt gemäss § nötigenfalls eine Verminderung der Höchstgeschwindigkeit bei der Reguliermethode?","Die EVU in den Betriebsvorschriften.",["Die ISB.","Das BAV.","Der LF."],F)
F="Bei der Fahrt gegen ein Halt zeigendes Signal, in ein Kopfgleis, in ein besetztes oder beschränkt ausnützbares Gleis oder gegen offene Barrieren ist die Geschwindigkeit des Zuges mit einer mässigen Bremsung rechtzeitig zu vermindern, so dass zum Anhalten oder im Notfall die Bremswirkung noch verstärkt werden kann. Die elektrische Bremse darf bei der Fahrt in ein Kopfgleis nur verwendet werden, wenn deren Wirkung bei einem allfälligen Ausfall gleichwertig und automatisch durch andere Bremsmittel kompensiert wird. Für Triebzüge gelten die entsprechenden Betriebsvorschriften des EVU."
addm("2.7.3","Halteort Hindernis","Bei welchen Fahrten ist die Geschwindigkeit des Zuges gemäss § mit einer mässigen Bremsung rechtzeitig zu vermindern (Mehrfachauswahl).",["Gegen ein Halt zeigendes Signal","In ein Kopfgleis","In ein besetztes oder beschränkt ausnützbares Gleis","Gegen offene Barrieren"],["Bei der Durchfahrt durch einen Tunnel","Bei der Fahrt über eine Brücke"],F)
add("2.7.3","Mässige Bremsung Zweck","Warum ist die Geschwindigkeit gemäss § mit einer mässigen Bremsung rechtzeitig zu vermindern?","Damit zum Anhalten oder im Notfall die Bremswirkung noch verstärkt werden kann.",["Damit der Zug ohne Bremsweg anhält.","Damit die elektrische Bremse geschont wird.","Damit die Bremssohlen nicht heiss werden."],F)
add("2.7.3","Kopfgleis elektrische Bremse","Wann darf die elektrische Bremse bei der Fahrt in ein Kopfgleis gemäss § nur verwendet werden?","Wenn deren Wirkung bei einem allfälligen Ausfall gleichwertig und automatisch durch andere Bremsmittel kompensiert wird.",["Wenn die Geschwindigkeit unter 40 km/h liegt.","Wenn der Zug nicht länger als 125 m ist.","Wenn der FDL zugestimmt hat."],F)
F="Vor dem Abhängen des Triebfahrzeugs ist die Anhängelast mit der automatischen Bremse zu bremsen. Während dem Wechseln des Führerstands ist das Triebfahrzeug bzw. der Pendelzug mit der automatischen Bremse oder nach den Vorgaben des EVU zu bremsen."
add("2.7.4","Abhängen Anhängelast","Womit ist die Anhängelast vor dem Abhängen des Triebfahrzeugs gemäss § zu bremsen?","Mit der automatischen Bremse.",["Mit der Rangierbremse.","Mit der Feststellbremse.","Mit der elektrischen Bremse."],F)
add("2.7.4","Führerstandswechsel","Womit ist das Triebfahrzeug bzw. der Pendelzug während dem Wechseln des Führerstands gemäss § zu bremsen?","Mit der automatischen Bremse oder nach den Vorgaben des EVU.",["Nur mit der Feststellbremse.","Nur mit der Rangierbremse.","Mit Hemmschuhen."],F)
F="Im Sinne der Bremsvorschriften gilt ein Unterbruch der Nachspeisung, welcher länger als zur Dichtheitsprobe notwendig ist, als Abstellen eines Zuges oder Zugteils. Wird die Nachspeisung unterbrochen, (z.B. bei der Ausserbetriebnahme des Führerstandes) ist eine Betriebsbremsung einzuleiten. So wird ein Erschöpfen der Bremsen bei langsamer Absenkung des Hauptleitungsdrucks vermieden."
add("2.7.5","Abstellen Zug","Was gilt gemäss § im Sinne der Bremsvorschriften als Abstellen eines Zuges oder Zugteils?","Ein Unterbruch der Nachspeisung, welcher länger als zur Dichtheitsprobe notwendig ist.",["Jeder Halt von mehr als 5 Minuten.","Das Abhängen des Triebfahrzeugs.","Das Ausschalten der Zugsammelschiene."],F)
add("2.7.5","Nachspeisung unterbrochen","Was ist gemäss § einzuleiten, wenn die Nachspeisung unterbrochen wird?","Eine Betriebsbremsung.",["Eine Schnellbremsung.","Eine Vollbremsung.","Ein Lösen mit Füllstellung."],F)
add("2.7.5","Erschöpfen Bremsen","Was wird gemäss § durch das Einleiten einer Betriebsbremsung bei unterbrochener Nachspeisung vermieden?","Ein Erschöpfen der Bremsen bei langsamer Absenkung des Hauptleitungsdrucks.",["Ein Überladen der Hauptleitung.","Ein Einfrieren der Bremssohlen.","Ein Ansprechen der Magnetschienenbremse."],F)
add("3.1.1","Art der Störung","Wie können Störungen an Luftbremsen gemäss § grundsätzlich auftreten?","Als Folge mangelhafter Bereitschaft oder wegen mangelhaftem Zustand.",["Nur als Folge mangelhafter Bereitschaft.","Nur wegen Abnützung.","Nur bei tiefen Temperaturen."],"Störungen an Luftbremsen können grundsätzlich als Folge mangelhafter Bereitschaft oder wegen mangelhaftem Zustand auftreten.")
F="Mangelhafte Bereitschaft der Bremse ist die Folge von unterlassener oder fehlerhafter Handhabung der Luftbremse bzw. einzelner Teile davon. Dazu gehören insbesondere: nicht oder falsch verbundene Luftleitungen; ganz oder teilweise in falscher Stellung stehende Kupplungs- oder Ausschalthahnen; Umstellvorrichtungen falsch oder in Zwischenstellung stehend; angezogene Feststellbremsen; überladene oder nicht oder nur ungenügend gefüllte bzw. evakuierte Bremsapparate."
add("3.1.2","Ursache mangelhafte Bereitschaft","Was ist gemäss § die Ursache mangelhafter Bereitschaft der Bremse?","Unterlassene oder fehlerhafte Handhabung der Luftbremse bzw. einzelner Teile davon.",["Abnützung und Alterung.","Das Eindringen von Fremdkörpern.","Trockenlauf von Kolben und Ventilen."],F)
addm("3.1.2","Mangelhafte Bereitschaft","Was gehört gemäss § insbesondere zur mangelhaften Bereitschaft der Bremse (Mehrfachauswahl).",["Nicht oder falsch verbundene Luftleitungen","Ganz oder teilweise in falscher Stellung stehende Kupplungs- oder Ausschalthahnen","Umstellvorrichtungen falsch oder in Zwischenstellung stehend","Angezogene Feststellbremsen","Überladene oder nicht oder nur ungenügend gefüllte bzw. evakuierte Bremsapparate"],["Defekte oder stark abgenutzte Bremssohlen","Lose Radreifen","Unterklotzte Tragfedern"],F)
F="Mangelhafter Zustand der Bremse macht sich bemerkbar durch Undichtheiten an Leitungen und Apparaten oder gehemmte Beweglichkeit von Kolben, Schiebern, Ventilen, usw. Die Ursachen sind oft Abnützung, Alterung, Trockenlauf oder das Eindringen von Fremdkörpern in die Leitungen und Apparate. Mangelhafte Zustände und daraus resultierende Störungen lassen sich unter anderem vermeiden, wenn unbenützte Schrauben- und Bremskupplungen sofort in die dafür bestimmten Halterungen verbracht werden und die Hauptleitung der Druckluftbremse sowie die Speiseleitung nach Möglichkeit vor dem Kuppeln kurz ausgeblasen werden."
addm("3.1.3","Mangelhafter Zustand Ursachen","Was sind gemäss § oft die Ursachen eines mangelhaften Zustands der Bremse (Mehrfachauswahl).",["Abnützung","Alterung","Trockenlauf","Eindringen von Fremdkörpern in die Leitungen und Apparate"],["Angezogene Feststellbremsen","Falsch stehende Umstellvorrichtungen"],F)
add("3.1.3","Mangelhafter Zustand Merkmal","Woran macht sich ein mangelhafter Zustand der Bremse gemäss § bemerkbar?","An Undichtheiten an Leitungen und Apparaten oder gehemmter Beweglichkeit von Kolben, Schiebern, Ventilen.",["An angezogenen Feststellbremsen.","An falsch stehenden Kupplungshahnen.","An nicht verbundenen Luftleitungen."],F)
add("3.1.3","Störungen vermeiden","Wie lassen sich mangelhafte Zustände und daraus resultierende Störungen gemäss § unter anderem vermeiden?","Unbenützte Schrauben- und Bremskupplungen sofort in die Halterungen verbringen und Hauptleitung sowie Speiseleitung vor dem Kuppeln kurz ausblasen.",["Die Hauptleitung nach dem Kuppeln lange ausblasen.","Die Kupplungen lose hängen lassen.","Die Speiseleitung nie ausblasen."],F)
F="Bei unklarer Ursache einer Bremsstörung ist das gestörte Fahrzeug bzw. der gestörte Zugteil zuerst auf die Bereitschaft und anschliessend auf den Zustand zu überprüfen. Kann die Störung nicht behoben werden, sind die Bremsen der gestörten Fahrzeuge nach Möglichkeit auszuschalten."
add("3.1.4","Störungsursache Reihenfolge","In welcher Reihenfolge ist das gestörte Fahrzeug bei unklarer Ursache einer Bremsstörung gemäss § zu überprüfen?","Zuerst auf die Bereitschaft und anschliessend auf den Zustand.",["Zuerst auf den Zustand und anschliessend auf die Bereitschaft.","Nur auf den Zustand.","Nur auf die Bereitschaft."],F)
add("3.1.4","Störung nicht behebbar","Was ist gemäss § zu tun, wenn eine Bremsstörung nicht behoben werden kann?","Die Bremsen der gestörten Fahrzeuge sind nach Möglichkeit auszuschalten.",["Die Fahrzeuge sind mit Schnellbremsung anzuhalten.","Die Bremsen sind angezogen zu lassen.","Die Fahrt ist ohne Massnahmen fortzusetzen."],F)
add("3.2.1","Plausibilitätsprüfung","Worauf hat der LF bei der Bremsprobe gemäss § insbesondere zu achten?","Ob ein der Länge der Hauptleitung entsprechend plausibel rasches oder langsames Fallen oder Steigen des Hauptleitungsdrucks vorliegt.",["Ob die Bremssohlen abgenützt sind.","Ob der Kompressor einwandfrei läuft.","Ob die Zugsammelschiene unter Spannung steht."],"Bei der Bremsprobe hat der LF insbesondere darauf zu achten, ob ein der Länge der Hauptleitung entsprechend plausibel rasches oder langsames Fallen oder Steigen des Hauptleitungsdrucks vorliegt.")
add("3.2.2","Angefrorene Bremssohlen","Was ist gemäss § bei festgestellten angefrorenen Bremssohlen bei klotzgebremsten Fahrzeugen zu tun?","Beim Lösen ist jeder Bremsklotz einzeln zu kontrollieren.",["Die Fahrzeuge sind sofort auszusetzen.","Die Bremsen sind mit dem Auslöseventil zu lösen.","Die Bremsklötze sind mit Hemmschuhen zu sichern."],"Werden angefrorene Bremssohlen festgestellt, ist bei klotzgebremsten Fahrzeugen beim Lösen jeder Bremsklotz einzeln zu kontrollieren.")
add("3.3.1","Nicht angeschlossene Fahrzeuge","Was ist gemäss § mit den Luftbremsen der nicht an die Hauptleitung des Triebfahrzeugs angeschlossenen Fahrzeuge zu tun?","Sie sind zu entleeren.",["Sie sind angezogen zu lassen.","Sie sind zu füllen.","Sie sind mit der Rangierbremse zu bedienen."],"Die Luftbremsen der nicht an die Hauptleitung des Triebfahrzeugs angeschlossenen Fahrzeuge sind zu entleeren.")
add("3.3.2","Ausfall Kompressor","Wann ist bei Ausfall des Kompressors während der Fahrt gemäss § anzuhalten?","Bevor der Hauptluftbehälterdruck unter den Wert des Normaldrucks der Hauptleitung gesunken ist.",["Sobald der Hauptluftbehälterdruck 3 bar erreicht.","Erst beim nächsten Bahnhof.","Wenn die Hauptleitung entleert ist."],"Bei Ausfall des Kompressors während der Fahrt ist anzuhalten, bevor der Hauptluftbehälterdruck unter den Wert des Normaldrucks der Hauptleitung gesunken ist.")
F="Sofern der Druckregler am Führerbremsventil von Hand verstellbar ist, kann der LF bei kleineren Überladungen durch Verstellen des Druckreglers den Hauptleitungsdruck erhöhen, bis alle Bremsen gelöst sind. Danach ist der Druck unter Beobachtung des Hauptleitungsmanometers durch langsames Zurückstellen des Druckreglers wieder auf den Normaldruck herabzusetzen. Wird infolge eines Defekts oder einer Fehlmanipulation beim Füllen die Bremse überladen und kann sie mit dem Normaldruck bzw. der Niederdrucküberladung nicht gelöst werden, ist der Hauptleitungsdruck auf 0,5 bar unter den Normaldruck herabzusetzen. Anschliessend sind die Auslöseventile der Wagen zu betätigen. Gegebenenfalls sind vorgängig ZVB bzw. ZBE zu verständigen."
add("3.3.3","Kleine Überladung","Was kann der LF bei kleineren Überladungen gemäss §, sofern der Druckregler von Hand verstellbar ist, tun?","Durch Verstellen des Druckreglers den Hauptleitungsdruck erhöhen, bis alle Bremsen gelöst sind.",["Die Auslöseventile aller Wagen betätigen.","Das Führerbremsventil in die Schnellbremsstellung bringen.","Die Hauptleitung entleeren."],F)
add("3.3.3","Überladung Rückstellen","Wie ist der Druck nach dem Lösen aller Bremsen bei kleineren Überladungen gemäss § wieder auf den Normaldruck herabzusetzen?","Unter Beobachtung des Hauptleitungsmanometers durch langsames Zurückstellen des Druckreglers.",["Durch rasches Zurückstellen des Druckreglers.","Durch eine Schnellbremsung.","Durch Betätigen der Auslöseventile."],F)
add("3.3.3","Überladung nicht lösbar","Auf welchen Wert ist der Hauptleitungsdruck gemäss § herabzusetzen, wenn die überladene Bremse mit Normaldruck bzw. Niederdrucküberladung nicht gelöst werden kann?","Auf 0,5 bar unter den Normaldruck.",["Auf 1 bar unter den Normaldruck.","Auf 0 bar.","Auf 0,3 bar unter den Normaldruck."],F)
add("3.3.3","Auslöseventile Überladung","Was ist nach dem Herabsetzen des Hauptleitungsdrucks bei einer nicht lösbaren Überladung gemäss § zu tun?","Die Auslöseventile der Wagen sind zu betätigen.",["Die Bremsen sind auszuschalten.","Der Hauptleitungsdruck ist über den Normaldruck zu erhöhen.","Die Wagen sind auszusetzen."],F)
add("3.3.4","Ungewolltes Bremsen","Was kann gemäss § versucht werden, wenn Wagen während der Fahrt bei dichter Hauptleitung ungewollt bremsen?","Die Wagen mit kurzzeitigem Bremsen und Lösen zu lösen, nach Möglichkeit mit Niederdrucküberladung.",["Eine Schnellbremsung einzuleiten.","Die Hauptleitung zu entleeren.","Die Speiseleitung abzusperren."],"Wenn während der Fahrt bei dichter Hauptleitung Wagen ungewollt bremsen, kann versucht werden, die Wagen mit kurzzeitigem Bremsen und Lösen zu lösen, nach Möglichkeit mit Niederdrucküberladung.")
F="Die Druckluftbremsen sind gegen geringe Undichtheiten unempfindlich. Starke Undichtheiten hingegen können zu Bremsstörungen am ganzen Zug führen. Kann eine solche Undichtheit nicht behoben oder durch das Ausschalten der Luftbremse umgangen werden, ist das betreffende Fahrzeug auszusetzen oder am Schluss des Zuges einzureihen."
add("3.3.5","Starke Undichtheit","Was ist gemäss § mit einem Fahrzeug zu tun, dessen starke Undichtheit nicht behoben oder durch das Ausschalten der Luftbremse umgangen werden kann?","Es ist auszusetzen oder am Schluss des Zuges einzureihen.",["Es ist an der Spitze des Zuges einzureihen.","Es ist mit angezogener Bremse mitzuführen.","Es ist in der Zugmitte zu belassen."],F)
add("3.3.5","Geringe Undichtheiten","Wie verhalten sich Druckluftbremsen gemäss § gegenüber geringen Undichtheiten?","Sie sind unempfindlich.",["Sie reagieren mit einer Zwangsbremsung.","Sie führen zu Bremsstörungen am ganzen Zug.","Sie lösen die Bremsen selbsttätig."],F)
add("3.4","Fahrzeuge ohne Ausschalteinrichtung","Wie ist gemäss § bei Fahrzeugen ohne Einrichtung zum Ausschalten der Bremsen zu verfahren?","Nach den Vorgaben des EVU.",["Das Fahrzeug ist sofort auszusetzen.","Die Hauptleitung ist abzusperren.","Das Fahrzeug ist am Schluss des Zuges einzureihen."],"Bei Fahrzeugen ohne Einrichtung zum Ausschalten der Bremsen ist nach den Vorgaben des EVU zu verfahren.")
F="Ist an einem Wagen die Luftbremse unbrauchbar, ist sie wie folgt auszuschalten: 1. Ausschalthahn schliessen; 2. Auslöseventil betätigen; 3. gelöster Zustand der Luftbremse ist mit einer Zusatzbremsprobe mittels Schnellbremsung am betreffenden Wagen zu prüfen. Müssen Luftbremsen aus betrieblichen Gründen ausgeschaltet werden, z.B. Güterzüge mit Anhängelast über 1200 t oder Fahrzeuge, an welchen die vorgeschriebene Stellung von Umstellvorrichtungen nicht vorhanden ist, genügt es, den gelösten Zustand der Luftbremse zu prüfen."
addm("3.4.1","Luftbremse ausschalten Schritte","Welche Schritte sind gemäss § zum Ausschalten einer unbrauchbaren Luftbremse an einem Wagen auszuführen (Mehrfachauswahl).",["Ausschalthahn schliessen","Auslöseventil betätigen","Gelösten Zustand der Luftbremse mit einer Zusatzbremsprobe mittels Schnellbremsung am betreffenden Wagen prüfen"],["Hauptleitung am Wagen entleeren und Kupplung lösen","Bremsklötze ausbauen"],F)
add("3.4.1","Ausschalten Reihenfolge","Welcher Schritt folgt gemäss § nach dem Schliessen des Ausschalthahns beim Ausschalten der Luftbremse eines Wagens?","Das Betätigen des Auslöseventils.",["Das Prüfen mit einer Zusatzbremsprobe.","Das Entleeren der Hauptleitung.","Das Anziehen der Feststellbremse."],F)
add("3.4.1","Ausschalten betrieblich","Was genügt gemäss § bei Luftbremsen, die aus betrieblichen Gründen ausgeschaltet werden müssen?","Es genügt, den gelösten Zustand der Luftbremse zu prüfen.",["Es ist eine Zusatzbremsprobe mittels Schnellbremsung durchzuführen.","Es ist keine Prüfung nötig.","Es ist eine Hauptbremsprobe durchzuführen."],F)
add("3.4.1","Anhängelast Ausschalten","Bei Güterzügen mit welcher Anhängelast müssen Luftbremsen gemäss § aus betrieblichen Gründen ausgeschaltet werden, wofür der gelöste Zustand zu prüfen genügt?","Über 1200 t.",["Über 600 t.","Über 800 t.","Über 2000 t."],F)
F="Die Luftbremse muss insbesondere bei defekten oder stark abgenutzten Bremssohlen, losen Radreifen, unterklotzten Tragfedern, Triebfahrzeugen mit demontierten Trieb- oder Kuppelstangen ausgeschaltet werden. Ist ein Ausschalten nicht möglich, müssen solche Fahrzeuge ausgesetzt werden."
addm("3.4.2","Luftbremse ausschalten bei","Bei welchen Schäden muss die Luftbremse gemäss § insbesondere ausgeschaltet werden (Mehrfachauswahl).",["Defekte oder stark abgenutzte Bremssohlen","Lose Radreifen","Unterklotzte Tragfedern","Triebfahrzeuge mit demontierten Trieb- oder Kuppelstangen"],["Angezogene Feststellbremse","Falsch stehender Kupplungshahn"],F)
add("3.4.2","Ausschalten nicht möglich","Was ist gemäss § mit Fahrzeugen mit Schäden an Fahrwerk und Bremsen zu tun, wenn die Luftbremse nicht ausgeschaltet werden kann?","Sie müssen ausgesetzt werden.",["Sie sind am Schluss des Zuges einzureihen.","Sie sind mit reduzierter Geschwindigkeit mitzuführen.","Sie sind zu entleeren und mitzuführen."],F)
add("3.4.3","Störung Gleitschutz","Was ist gemäss § bei gestörtem Gleitschutz am betreffenden Wagen zu tun?","Die Umstellvorrichtung für Bremswirkung ist auf P/RIC zu stellen; ist das nicht möglich, ist die Luftbremse auszuschalten.",["Die Umstellvorrichtung ist auf G zu stellen.","Der Wagen ist sofort auszusetzen.","Der Gleitschutz ist durch Sanden zu ersetzen."],"Ist der Gleitschutz gestört, muss am betreffenden Wagen die Umstellvorrichtung für Bremswirkung auf P/RIC gestellt werden. Ist das nicht möglich, ist die Luftbremse auszuschalten.")
add("3.5","Störung Mg-Bremse","Wie ist gemäss § bei Störungen an der Mg-Bremse zu verfahren?","Nach den Vorgaben des EVU.",["Der Zug ist sofort anzuhalten.","Die Luftbremse ist auszuschalten.","Die Hauptleitung ist zu entleeren."],"Bei Störungen an der Mg-Bremse ist nach den Vorgaben des EVU zu verfahren.")
F="Sind während der Fahrt im Zug Anzeichen wahrnehmbar, die auf das Ansprechen einzelner Bremsen hindeuten, hat der LF wo möglich eine Dichtigkeitsprobe vorzunehmen. Ist bei der Durchführung der Dichtigkeitsprobe ein Druckverlust in der Hauptleitung feststellbar, ist der Zug anzuhalten."
add("3.6.1","Dichtigkeitsprobe Fahrt","Was hat der LF gemäss § wo möglich zu tun, wenn im Zug während der Fahrt Anzeichen wahrnehmbar sind, die auf das Ansprechen einzelner Bremsen hindeuten?","Eine Dichtigkeitsprobe vorzunehmen.",["Eine Schnellbremsung einzuleiten.","Die Luftbremse auszuschalten.","Die Hauptleitung zu entleeren."],F)
add("3.6.1","Druckverlust Dichtigkeitsprobe","Was ist gemäss § zu tun, wenn bei der Dichtigkeitsprobe während der Fahrt ein Druckverlust in der Hauptleitung feststellbar ist?","Der Zug ist anzuhalten.",["Die Fahrt ist mit reduzierter Geschwindigkeit fortzusetzen.","Die Probe ist zu wiederholen.","Es ist bis zum nächsten Bahnhof weiterzufahren."],F)
add("3.6.2","Sinkender Hauptleitungsdruck","Was hat der LF gemäss § zu tun, wenn er ohne Dichtigkeitsprobe ein Absinken des Hauptleitungsdrucks unter den eingestellten Wert bemerkt?","Das Führerbremsventil sofort in die Schnellbremsstellung zu verbringen.",["Das Führerbremsventil in der Fahrstellung zu belassen.","Eine Dichtigkeitsprobe durchzuführen.","Eine Betriebsbremsung einzuleiten."],"Bemerkt der LF ohne Dichtigkeitsprobe ein Absinken des Hauptleitungsdrucks unter den eingestellten Wert, so ist das Führerbremsventil sofort in die Schnellbremsstellung zu verbringen.")
F="Vermutet der LF bei sinkendem Hauptleitungsdruck eine Zugtrennung, ist das Führerbremsventil in der Fahrstellung zu belassen. Kurz vor dem Halt ist das Führerbremsventil in die Betriebsbremsstellung zu verbringen."
add("3.6.3","Vermutete Zugtrennung","Was hat der LF gemäss § bei sinkendem Hauptleitungsdruck und vermuteter Zugtrennung zu tun?","Das Führerbremsventil in der Fahrstellung belassen.",["Das Führerbremsventil sofort in die Schnellbremsstellung bringen.","Sofort eine Vollbremsung einleiten.","Das Führerbremsventil in die Füllstellung bringen."],F)
add("3.6.3","Zugtrennung Halt","Wann ist das Führerbremsventil bei vermuteter Zugtrennung gemäss § in die Betriebsbremsstellung zu verbringen?","Kurz vor dem Halt.",["Sofort bei Feststellung.","Nie.","Erst nach dem Halt."],F)
F="Wenn bei Gefahr ein sofortiges Anhalten des Zuges notwendig ist, haben die LF aller an die Hauptleitung angeschlossenen Lokomotiven den Zug mit einer Schnellbremsung anzuhalten bzw. die auf der Spitzenlok ausgelöste Schnellbremsung ist zu unterstützen. Dabei ist die Luftbremse ohne Rücksicht auf die elektrische Bremse sofort zu benützen und auf den Triebfahrzeugen ebenfalls voll wirken zu lassen. Eine Schnellbremsung ist auch auszuführen, wenn die beabsichtigte Wirkung einer Betriebsbremsung trotz starker Verminderung des Drucks in der Hauptleitung nicht erreicht wird. Zudem ist der Zug nötigenfalls mit allen verfügbaren Mitteln zu bremsen. Dazu zählen insbesondere die Nottaste, der Nothahn und das Ansprechenlassen von Sicherheitseinrichtungen."
add("3.7.1","Anhalten bei Gefahr","Wie haben die LF aller an die Hauptleitung angeschlossenen Lokomotiven den Zug gemäss § bei Gefahr anzuhalten?","Mit einer Schnellbremsung bzw. die auf der Spitzenlok ausgelöste Schnellbremsung unterstützen.",["Mit einer Betriebsbremsung.","Mit der elektrischen Bremse.","Mit der Rangierbremse."],F)
add("3.7.1","Gefahr Luftbremse","Wie ist die Luftbremse bei Gefahr gemäss § zu benützen?","Ohne Rücksicht auf die elektrische Bremse sofort, und auf den Triebfahrzeugen ebenfalls voll wirken lassen.",["Erst nach Ausfall der elektrischen Bremse.","Nur auf den Wagen, nicht auf den Triebfahrzeugen.","Nur mit halber Wirkung."],F)
add("3.7.1","Schnellbremsung Wirkung ausbleibt","Wann ist gemäss § auch eine Schnellbremsung auszuführen?","Wenn die beabsichtigte Wirkung einer Betriebsbremsung trotz starker Verminderung des Drucks in der Hauptleitung nicht erreicht wird.",["Bei jedem Halt vor einem Signal.","Bei jeder Gefällefahrt.","Bei jedem Lösen der Bremse."],F)
addm("3.7.1","Mittel bei Gefahr","Welche Mittel zählen gemäss § insbesondere zu den Mitteln, mit denen der Zug nötigenfalls zu bremsen ist (Mehrfachauswahl).",["Die Nottaste","Der Nothahn","Das Ansprechenlassen von Sicherheitseinrichtungen"],["Das Auslösen der Luftbremse","Das Abschalten der Zugsammelschiene"],F)
F="Bei schlechten Adhäsionsverhältnissen hat der LF vorausschauend und nötigenfalls ohne Rücksicht auf allfällige Zeitverluste mit stark reduzierter Geschwindigkeit zu fahren. In kritischen Situationen sind, sofern vorhanden, die Sander zu betätigen. Die erforderliche Bremskraft soll möglichst von allen Achsen aufgebracht werden. Zu grosse Bremskräfte mit der Luft- oder mit der elektrischen Bremse sind möglichst zu vermeiden. Bei der Einfahrt in Gefälle ist die Bremsung rechtzeitig und vor dem Erreichen der Höchstgeschwindigkeit einzuleiten."
addm("3.7.2","Schlechte Adhäsion","Wie hat sich der LF bei schlechten Adhäsionsverhältnissen gemäss § zu verhalten (Mehrfachauswahl).",["Vorausschauend und nötigenfalls ohne Rücksicht auf Zeitverluste mit stark reduzierter Geschwindigkeit fahren","In kritischen Situationen, sofern vorhanden, die Sander betätigen","Die erforderliche Bremskraft möglichst von allen Achsen aufbringen","Bei der Einfahrt in Gefälle rechtzeitig und vor dem Erreichen der Höchstgeschwindigkeit bremsen"],["Zu grosse Bremskräfte mit der Luft- oder elektrischen Bremse anwenden","Die Geschwindigkeit trotz Zeitverlusten beibehalten"],F)
_a,_m=add,addm
def add(z,t,q,g,b,f): _a(z+" (Beilage 1)",t,q,g,b,f)
def addm(z,t,q,g,b,f): _m(z+" (Beilage 1)",t,q,g,b,f)
add("1.1","Zweck Bremsen","Wozu dienen die Bremsen gemäss §?","Dem Regulieren der Geschwindigkeit und zum Anhalten von Zügen bzw. Rangierbewegungen.",["Nur dem Anhalten bei Gefahr.","Nur dem Sichern abgestellter Fahrzeuge.","Dem Erhöhen der Haftreibung zwischen Rad und Schiene."],"Die Bremsen dienen dem Regulieren der Geschwindigkeit und zum Anhalten von Zügen bzw. Rangierbewegungen.")
F="In der Regel werden Eisenbahnfahrzeuge gebremst mit Reibungsbremsen, mit elektrischen Bremsen, mit Schienenbremsen, mit Zahnradbremsen, mit weiteren Systemen ohne mechanische Reibung (z.B. Wirbelstrombremsen, hydrostatische oder hydrodynamische Bremsen)."
addm("1.2","Bremssysteme","Wie werden Eisenbahnfahrzeuge gemäss § in der Regel gebremst (Mehrfachauswahl).",["Mit Reibungsbremsen","Mit elektrischen Bremsen","Mit Schienenbremsen","Mit Zahnradbremsen"],["Mit Pendelbremsen","Mit Fliehkraftbremsen"],F)
F="Als Reibungsbremsen werden hauptsächlich Klotz- oder Scheibenbremsen verwendet. Bei der Klotzbremse werden Bremssohlen aus Grauguss oder Verbundstoff an die Lauffläche der Räder aus Stahl gepresst. Bei der Scheibenbremse werden Bremsbeläge auf eine am Radsatz befestigte Scheibe gepresst. In der Regel werden Reibungsbremsen als Luftbremsen ausgeführt."
add("1.2.1","Reibungsbremsen","Welche Bauarten werden als Reibungsbremsen gemäss § hauptsächlich verwendet?","Klotz- oder Scheibenbremsen.",["Magnetschienen- oder Wirbelstrombremsen.","Zahnrad- oder Schienenbremsen.","Nutzstrom- oder Widerstandsbremsen."],F)
add("1.2.1","Klotzbremse","Was wird bei der Klotzbremse gemäss § an die Lauffläche der Räder aus Stahl gepresst?","Bremssohlen aus Grauguss oder Verbundstoff.",["Bremsbeläge auf eine Scheibe.","Bremsschuhe aus Stahl.","Bremsbänder aus Gummi."],F)
add("1.2.1","Scheibenbremse","Was wird bei der Scheibenbremse gemäss § auf eine am Radsatz befestigte Scheibe gepresst?","Bremsbeläge.",["Bremssohlen aus Grauguss.","Bremsschuhe.","Bremsbänder."],F)
F="Die meisten Triebfahrzeuge sowie Reisezug- und die meisten Güterwagen sind zudem mit einer von Hand zu betätigenden mechanischen Reibungsbremse ausgerüstet. Dabei wird unterschieden zwischen vom Fahrzeug oder vom Boden aus bedienbaren Bremsen, die der Sicherung von Fahrzeugen gegen Entlaufen dienen und nur vom Fahrzeug aus bedienbaren Bremsen, die einerseits der Sicherung von Fahrzeugen gegen Entlaufen und andererseits dem Regulieren der Geschwindigkeit für bestimmte Rangierbewegungen dienen."
add("1.2.1","Handbremse Boden","Wozu dienen von Hand zu betätigende Bremsen, die vom Fahrzeug oder vom Boden aus bedienbar sind, gemäss §?","Der Sicherung von Fahrzeugen gegen Entlaufen.",["Dem Regulieren der Geschwindigkeit im Gefälle.","Dem Verkürzen des Bremswegs bei Schnellbremsung.","Dem Kompensieren der elektrischen Bremse."],F)
add("1.2.1","Handbremse nur Fahrzeug","Wozu dienen von Hand zu betätigende Bremsen, die nur vom Fahrzeug aus bedienbar sind, gemäss § einerseits und andererseits?","Der Sicherung gegen Entlaufen und dem Regulieren der Geschwindigkeit für bestimmte Rangierbewegungen.",["Nur der Sicherung gegen Entlaufen.","Nur dem Regulieren der Geschwindigkeit im Gefälle.","Dem Anhalten bei Gefahr und dem Lösen der Luftbremse."],F)
F="Bei der elektrischen Bremse wirken die Triebmotoren der Triebfahrzeuge als Generatoren. Die dadurch gewonnene elektrische Energie wird bei der Nutzstrombremse ins Fahrleitungsnetz zurückgespeist, bei der Widerstandsbremse über Widerstände in Wärmeenergie umgewandelt."
add("1.2.2","Elektrische Bremse Prinzip","Wie wirken die Triebmotoren bei der elektrischen Bremse gemäss §?","Als Generatoren.",["Als Transformatoren.","Als Kompressoren.","Als Elektromagnete."],F)
add("1.2.2","Nutzstrombremse","Was geschieht gemäss § bei der Nutzstrombremse mit der gewonnenen elektrischen Energie?","Sie wird ins Fahrleitungsnetz zurückgespeist.",["Sie wird über Widerstände in Wärmeenergie umgewandelt.","Sie wird in Batterien gespeichert.","Sie wird für die Bremszylinder verwendet."],F)
add("1.2.2","Widerstandsbremse","Was geschieht gemäss § bei der Widerstandsbremse mit der gewonnenen elektrischen Energie?","Sie wird über Widerstände in Wärmeenergie umgewandelt.",["Sie wird ins Fahrleitungsnetz zurückgespeist.","Sie wird in Batterien gespeichert.","Sie wird in die Zugsammelschiene eingespeist."],F)
F="Die elektrische Bremse dient dem Regulieren und Vermindern der Geschwindigkeit, in gewissen Fällen bis zum Halt. Sie hat zudem folgende Vorteile: Der Verschleiss der mechanischen Bremsen ist geringer; Die Lärmemissionen sind geringer; Bei Gefällefahrten werden die Räder weniger erwärmt; Die Zugführung wird erleichtert; Bei Gefahr besteht eine erhöhte Bremsbereitschaft der automatischen Bremse."
addm("1.2.2","Vorteile elektrische Bremse","Welche Vorteile hat die elektrische Bremse gemäss § (Mehrfachauswahl).",["Der Verschleiss der mechanischen Bremsen ist geringer","Die Lärmemissionen sind geringer","Bei Gefällefahrten werden die Räder weniger erwärmt","Die Zugführung wird erleichtert","Bei Gefahr besteht eine erhöhte Bremsbereitschaft der automatischen Bremse"],["Der Bremsweg ist immer kürzer als bei der Luftbremse","Die Fahrleitung wird entlastet"],F)
add("1.2.3","Schienenbremse","Wie wirkt die Schienenbremse gemäss §?","Bremsschuhe werden unter dem Fahrgestell abgesenkt und in der Regel durch Magnetkraft auf den Schienenkopf gepresst.",["Bremsbeläge werden auf eine Scheibe am Radsatz gepresst.","Die Triebmotoren wirken als Generatoren.","Eine Feder im Bremszylinder drückt auf die Räder."],"Bei der Schienenbremse werden Bremsschuhe unter dem Fahrgestell abgesenkt und in der Regel durch Magnetkraft auf den Schienenkopf gepresst.")
F="Die automatische Bremse ist eine durchgehende Bremse, mit der sämtliche daran angeschlossenen Fahrzeuge eines Zuges oder einer Rangierbewegung von einer Stelle aus bedient werden können. Die automatische Bremse muss jederzeit das Anhalten ermöglichen; bei einer Zugtrennung auf jeden Zugteil automatisch wirken; im Notfall von jedem Fahrzeug aus, auf dem sich während der Fahrt Personen befinden, betätigt oder angefordert werden können; unabhängig von einer Energiequelle ausserhalb des Fahrzeugs ausreichend lange wirksam sein."
addm("1.3","Anforderungen automatische Bremse","Was muss die automatische Bremse gemäss § erfüllen (Mehrfachauswahl).",["Jederzeit das Anhalten ermöglichen","Bei einer Zugtrennung auf jeden Zugteil automatisch wirken","Im Notfall von jedem Fahrzeug aus, auf dem sich Personen befinden, betätigt oder angefordert werden können","Unabhängig von einer Energiequelle ausserhalb des Fahrzeugs ausreichend lange wirksam sein"],["Nur vom Führerstand aus betätigt werden können","Nur bei Zugtrennung wirken"],F)
add("1.3","Automatische Bremse durchgehend","Was kennzeichnet die automatische Bremse gemäss § als durchgehende Bremse?","Sämtliche daran angeschlossenen Fahrzeuge eines Zuges oder einer Rangierbewegung können von einer Stelle aus bedient werden.",["Sie wirkt nur auf das bediente Fahrzeug.","Sie wirkt nur auf die Triebfahrzeuge.","Sie muss an jedem Fahrzeug einzeln bedient werden."],F)
add("1.3","Bauart automatische Bremse","Als welche Bauart werden automatische Bremsen gemäss § in der Regel gebaut?","Als indirekt wirkende Luftbremsen (automatische Druckluftbremse, Vakuumbremse).",["Als direkt wirkende Luftbremsen.","Als rein mechanische Bremsen.","Als Federspeicherbremsen."],"Automatische Bremsen werden in der Regel als indirekt wirkende Luftbremsen gebaut (automatische Druckluftbremse, Vakuumbremse). Weiter werden auch direkt wirkende Luftbremsen, elektro-pneumatische, elektro-hydraulische oder rein elektrische Bremsen als automatische Bremsen verwendet.")
F="Luftbremsen werden hauptsächlich verwendet als automatische Bremse und Rangierbremse. Die mittels Kompressor erzeugte Druckluft dient bei der automatischen Bremse nicht nur der Krafterzeugung, sondern auch der Steuerung des Bremsvorgangs. Die Rangierbremse wirkt direkt auf das bediente Fahrzeug (Triebfahrzeug oder Steuerwagen) und gegebenenfalls auf das vielfach- oder ferngesteuerte Fahrzeug."
add("1.4","Rangierbremse Wirkung","Auf welche Fahrzeuge wirkt die Rangierbremse gemäss §?","Direkt auf das bediente Fahrzeug (Triebfahrzeug oder Steuerwagen) und gegebenenfalls auf das vielfach- oder ferngesteuerte Fahrzeug.",["Auf sämtliche Fahrzeuge des Zuges.","Nur auf die Wagen der Anhängelast.","Nur auf das letzte Fahrzeug."],F)
add("1.4","Druckluft automatische Bremse","Wozu dient die mittels Kompressor erzeugte Druckluft bei der automatischen Bremse gemäss §?","Nicht nur der Krafterzeugung, sondern auch der Steuerung des Bremsvorgangs.",["Nur der Krafterzeugung.","Nur der Steuerung des Bremsvorgangs.","Nur dem Lösen der Feststellbremse."],F)
F="Die vom Bremsklotz auf das Rad wirkende Reibungskraft darf nie grösser werden als die vom Rad auf die Schiene übertragbare Haftreibungskraft, ansonsten die Räder zum Gleiten kommen und Flachstellen entstehen. Diese physikalische Gegebenheit bewirkt, dass aufgrund der im Vergleich zu Strassenfahrzeugen geringen Haftreibung erheblich längere Bremswege resultieren. Höchstdruckbegrenzer verhindern einen übermässigen Druck im Bremszylinder und ein dadurch entstehendes Gleiten der Räder."
add("2.1","Reibungskraft Grenze","Was geschieht gemäss §, wenn die Reibungskraft des Bremsklotzes grösser wird als die übertragbare Haftreibungskraft zwischen Rad und Schiene?","Die Räder kommen zum Gleiten und es entstehen Flachstellen.",["Die Bremswirkung nimmt zu.","Die Bremsen lösen selbsttätig.","Die Schienen werden magnetisiert."],F)
add("2.1","Höchstdruckbegrenzer","Was verhindern Höchstdruckbegrenzer gemäss §?","Einen übermässigen Druck im Bremszylinder und ein dadurch entstehendes Gleiten der Räder.",["Ein Überladen der Hauptleitung.","Ein Einfrieren der Bremssohlen.","Ein Ansprechen der Schnellbremse."],F)
add("2.1","Bremswege Eisenbahn","Weshalb resultieren bei Eisenbahnfahrzeugen gemäss § im Vergleich zu Strassenfahrzeugen erheblich längere Bremswege?","Wegen der geringen Haftreibung.",["Wegen der geringeren Masse.","Wegen der fehlenden Bremsen an den Wagen.","Wegen der höheren Haftreibung."],F)
F="Der Haftreibungswert zwischen Rad und Schiene ist bei sauberen, trockenen oder vollständig nassen Schienen am grössten. Bei beginnendem Regen, bei Nebel, Raureif, auf Bahnübergängen wegen Streusalz, besonders aber bei Laubfall oder Verschmutzung mit Öl, können die Schienen rutschig und der Haftreibungswert sehr klein werden. Gleitschutzvorrichtungen verhindern das Gleiten, allenfalls hilft auch das Sanden."
add("2.2","Haftreibung gross","Bei welchem Schienenzustand ist der Haftreibungswert zwischen Rad und Schiene gemäss § am grössten?","Bei sauberen, trockenen oder vollständig nassen Schienen.",["Bei beginnendem Regen.","Bei Raureif.","Bei Laubfall."],F)
addm("2.2","Haftreibung klein","Wann können die Schienen gemäss § rutschig und der Haftreibungswert sehr klein werden (Mehrfachauswahl).",["Bei beginnendem Regen","Bei Nebel","Bei Raureif","Auf Bahnübergängen wegen Streusalz","Bei Laubfall oder Verschmutzung mit Öl"],["Bei sauberen, trockenen Schienen","Bei vollständig nassen Schienen"],F)
F="Der Reibungswert zwischen Bremssohle und Rad ist von der Geschwindigkeit, der Flächenpressung der Bremssohle sowie der Materialpaarung Rad / Bremssohle abhängig. Mit zunehmender Geschwindigkeit nimmt bei Bremssohlen aus Grauguss der Reibungswert relativ stark ab, bei Bremssohlen aus Verbundstoff (z.B. K, L und LL) nur schwach ab und bleibt bei Scheibenbremsen konstant."
add("2.3","Reibungswert Grauguss","Wie verändert sich der Reibungswert bei Bremssohlen aus Grauguss mit zunehmender Geschwindigkeit gemäss §?","Er nimmt relativ stark ab.",["Er nimmt nur schwach ab.","Er bleibt konstant.","Er nimmt zu."],F)
add("2.3","Reibungswert Verbundstoff","Wie verändert sich der Reibungswert bei Bremssohlen aus Verbundstoff (z.B. K, L und LL) mit zunehmender Geschwindigkeit gemäss §?","Er nimmt nur schwach ab.",["Er nimmt relativ stark ab.","Er bleibt konstant.","Er nimmt zu."],F)
add("2.3","Reibungswert Scheibenbremse","Wie verändert sich der Reibungswert bei Scheibenbremsen mit zunehmender Geschwindigkeit gemäss §?","Er bleibt konstant.",["Er nimmt relativ stark ab.","Er nimmt nur schwach ab.","Er nimmt zu."],F)
addm("2.3","Reibungswert abhängig","Wovon ist der Reibungswert zwischen Bremssohle und Rad gemäss § abhängig (Mehrfachauswahl).",["Von der Geschwindigkeit","Von der Flächenpressung der Bremssohle","Von der Materialpaarung Rad / Bremssohle"],["Von der Länge des Zuges","Von der Temperatur der Fahrleitung"],F)
F="Durch die Abnützung der Bremssohlen und Radreifen vergrössert sich das Spiel zwischen Bremssohle und Rad. Dies bedeutet vermehrten Verbrauch an Druckluft sowie längere Bremszylinderfüll- und Lösezeiten aufgrund des grösseren Weges. Mit einem im Bremsgestänge eingebauten, in der Regel automatischen Gestängesteller, werden diese Nachteile behoben. Dieser sorgt dafür, dass die Bremssohlenabnützung durch Verkürzen einer Bremszugstange kompensiert wird, damit das Klotzspiel und der Kolbenhub nicht grösser werden."
add("3.3","Bremsgestängesteller Zweck","Was bewirkt ein Bremsgestängesteller gemäss §?","Er kompensiert die Bremssohlenabnützung durch Verkürzen einer Bremszugstange, damit Klotzspiel und Kolbenhub nicht grösser werden.",["Er passt den Bremsklotzdruck an das Wagengewicht an.","Er verhindert das Gleiten der Räder.","Er begrenzt den Druck im Bremszylinder."],F)
add("3.4","Lastabbremsung","Was ermöglicht die Lastabbremsung gemäss §?","Das Anpassen des Bremsklotzdrucks an das effektive Wagengewicht.",["Das Anpassen der Füllzeit an die Zuglänge.","Das Verkürzen der Bremszugstange.","Das Verhindern des Gleitens der Räder."],"Wagen, bei denen das Bruttogewicht erheblich grösser ist als das Leergewicht, sind mit einer Lastabbremsung ausgerüstet. Diese Einrichtung ermöglicht das Anpassen des Bremsklotzdrucks an das effektive Wagengewicht.")
add("4","Atmosphärischer Druck","Welchem Druck entspricht der Druck der Luftschicht der Erdatmosphäre gemäss § ca.?","Ca. 1 bar.",["Ca. 5 bar.","Ca. 0,1 bar.","Ca. 10 bar."],"Die Luftschicht der Erdatmosphäre drückt auf die Erde ungefähr so stark wie das Gewicht einer Wassersäule von 10 m Höhe oder einer Quecksilbersäule von 760 mm Höhe. Das entspricht je cm2 Erdoberfläche rund 10 N (1 kp) oder ca. 1 bar.")
F="Druckluft strömt in einer Leitung stets von der Stelle des höheren zur Stelle des tieferen Drucks. Die Strömungsgeschwindigkeit ist abhängig von der Höhe des Druckunterschieds und dem Widerstand in der Leitung."
add("4.1","Strömungsrichtung Druckluft","In welche Richtung strömt Druckluft in einer Leitung gemäss § stets?","Von der Stelle des höheren zur Stelle des tieferen Drucks.",["Von der Stelle des tieferen zur Stelle des höheren Drucks.","Immer vom Hauptluftbehälter weg.","Immer in Fahrtrichtung."],F)
add("4.1","Strömungsgeschwindigkeit","Wovon ist die Strömungsgeschwindigkeit der Druckluft in einer Leitung gemäss § abhängig?","Von der Höhe des Druckunterschieds und dem Widerstand in der Leitung.",["Von der Länge des Zuges.","Von der Aussentemperatur allein.","Von der Zahl der Bremszylinder."],F)
add("4.2","Vakuum Entstehung","Wie entsteht ein Vakuum gemäss §?","Aus einem geschlossenen Raum wird mit einer Vakuumpumpe die Luft abgesaugt, sodass gegenüber dem atmosphärischen Druck ein Unterdruck entsteht.",["Luft wird auf einen Teil ihres Volumens zusammengedrückt.","Luft wird über den Kompressor eingeblasen.","Der Druck wird mit einem Druckregler erhöht."],"Ein Vakuum entsteht, wenn aus einem geschlossenen Raum mit einer Vakuumpumpe die Luft abgesaugt wird und dadurch gegenüber dem atmosphärischen Druck ein Unterdruck entsteht.")
F="Die Hauptleitung verbindet, ausgehend vom Führerbremsventil des bedienten Führerstandes, sämtliche an die automatische Bremse angeschlossenen Fahrzeuge bis zum Zugende. Sie versorgt die Fahrzeuge mit der zur Krafterzeugung und Steuerung der Bremse nötigen Druckluft bzw. Vakuum."
add("5.1.1","Hauptleitung Funktion","Was verbindet die Hauptleitung gemäss §?","Ausgehend vom Führerbremsventil des bedienten Führerstandes sämtliche an die automatische Bremse angeschlossenen Fahrzeuge bis zum Zugende.",["Den Hauptluftbehälter mit dem Kompressor.","Nur die Triebfahrzeuge in Vielfachsteuerung.","Das Rangierbremsventil mit den Bremszylindern."],F)
F="Zum Absperren der Hauptleitung an Fahrzeugen mit Druckluftbremse ist an jedem Stossbalken ein Kupplungshahn vorhanden. Der Kupplungshahn ist offen, wenn sich dessen Griff in der Regel in waagrechter Stellung befindet und geschlossen, wenn sich der Griff in der Regel in senkrechter Stellung befindet. In geschlossener Stellung wird die Bremskupplung durch eine Bohrung im Hahngehäuse mit dem Freien verbunden und dadurch entlüftet."
add("5.1.1","Kupplungshahn offen","In welcher Stellung des Griffs ist der Kupplungshahn der Hauptleitung bei Druckluftbremse gemäss § in der Regel offen?","In waagrechter Stellung.",["In senkrechter Stellung.","In schräger Stellung nach unten.","In Zwischenstellung."],F)
add("5.1.1","Kupplungshahn geschlossen","In welcher Stellung des Griffs ist der Kupplungshahn der Hauptleitung bei Druckluftbremse gemäss § in der Regel geschlossen?","In senkrechter Stellung.",["In waagrechter Stellung.","In schräger Stellung nach oben.","In Zwischenstellung."],F)
add("5.1.1","Kupplungshahn geschlossen Entlüftung","Was geschieht gemäss § mit der Bremskupplung, wenn der Kupplungshahn geschlossen ist?","Sie wird durch eine Bohrung im Hahngehäuse mit dem Freien verbunden und dadurch entlüftet.",["Sie bleibt unter Druck.","Sie wird mit der Speiseleitung verbunden.","Sie wird mit dem Hilfsluftbehälter verbunden."],F)
add("5.1.1","Vakuum Blinddeckel","Wie wird die Hauptleitung an Fahrzeugen mit Vakuumbremse gemäss § abgesperrt?","Mit einem Blinddeckel an den Kupplungsköpfen, der sich bei erzeugtem Vakuum festsaugt.",["Mit einem Kupplungshahn am Stossbalken.","Mit einem Rückschlagventil.","Mit einem Auslöseventil."],"Zum Absperren der Hauptleitung an Fahrzeugen mit Vakuumbremse ist an den Kupplungsköpfen der Bremskupplung ein Blinddeckel angebracht. Dieser saugt sich bei erzeugtem Vakuum auf dem Kupplungskopf fest.")
F="Die Speiseleitung versorgt ab dem Hauptluftbehälter des Triebfahrzeugs die angeschlossenen Fahrzeuge mit Druckluft. Für die Funktion der Bremsen ist das Kuppeln der Speiseleitung zwingend zum Versorgen des Führerbrems- und Rangierbremsventils eines vom Steuerwagen aus geführten Zuges mit Druckluft; zum Versorgen der Bremszylinder mit Druckluft für Fahrzeuge mit direkt wirkender elektropneumatischer Bremse; zum Versorgen der Bremszylinder mit Druckluft für Fahrzeuge mit vakuumgesteuerter Druckluftbremse."
addm("5.1.2","Speiseleitung zwingend","In welchen Fällen ist das Kuppeln der Speiseleitung für die Funktion der Bremsen gemäss § zwingend (Mehrfachauswahl).",["Zum Versorgen des Führerbrems- und Rangierbremsventils eines vom Steuerwagen aus geführten Zuges","Für Fahrzeuge mit direkt wirkender elektropneumatischer Bremse","Für Fahrzeuge mit vakuumgesteuerter Druckluftbremse"],["Für Wagen mit Handbremse","Für Fahrzeuge mit Federspeicherbremse"],F)
add("5.1.3","Rangierbremsleitung","Was dient bei der Rangierbremsleitung gemäss § in der Regel zum Absperren?","Ein in die Kupplungsköpfe integriertes Rückschlagventil.",["Ein Kupplungshahn am Stossbalken.","Ein Blinddeckel.","Ein Auslöseventil."],"Die Rangierbremsleitung versorgt, ausgehend vom Rangierbremsventil des bedienten Führerstands, die in Vielfachsteuerung angeschlossenen Triebfahrzeuge mit Druckluft für deren Rangierbremse. Die Rangierbremsleitung besitzt in der Regel keine Absperrhahnen. Zum Absperren dient ein in die Kupplungsköpfe integriertes Rückschlagventil.")
F="Die automatische Druckluftbremse wird auch als indirekt wirkende Bremse bezeichnet, da die Druckluft dem Bremszylinder indirekt über das Steuerventil aus dem Hilfsluftbehälter zugeführt wird, welches durch den Hauptleitungsdruck gesteuert ist. Die automatische Bremse kann in der Regel an jedem Fahrzeug separat ausser Betrieb gesetzt werden. Bei Wagen geschieht das mit einem aussen am Fahrzeug angebrachten Ausschalthahn. In der Regel ist dieser offen, wenn sich dessen Griff in senkrechter Stellung befindet und geschlossen, wenn sich der Griff in waagrechter Stellung befindet."
add("6.1","Indirekt wirkend","Weshalb wird die automatische Druckluftbremse gemäss § auch als indirekt wirkende Bremse bezeichnet?","Die Druckluft wird dem Bremszylinder indirekt über das Steuerventil aus dem Hilfsluftbehälter zugeführt.",["Die Bremse wird indirekt über die Rangierbremse bedient.","Die Bremse wirkt indirekt über die Schiene.","Die Druckluft wird direkt aus dem Hauptluftbehälter zugeführt."],F)
add("6.1","Ausschalthahn offen","In welcher Stellung des Griffs ist der Ausschalthahn am Wagen gemäss § in der Regel offen?","In senkrechter Stellung.",["In waagrechter Stellung.","In schräger Stellung nach oben.","In Zwischenstellung."],F)
add("6.1","Ausschalthahn geschlossen","In welcher Stellung des Griffs ist der Ausschalthahn am Wagen gemäss § in der Regel geschlossen?","In waagrechter Stellung.",["In senkrechter Stellung.","In schräger Stellung nach unten.","In Zwischenstellung."],F)
addm("6.1","Ausrüstung Fahrzeuge Druckluftbremse","Womit sind Fahrzeuge mit automatischer Druckluftbremse gemäss § mindestens ausgerüstet (Mehrfachauswahl).",["Hauptleitung","Ausschalthahn","Steuerventil mit bzw. ohne Steuerbehälter","Hilfsluftbehälter","Bremszylinder"],["Kompressor","Hauptluftbehälter","Führerbremsventil"],"Fahrzeuge mit automatischer Druckluftbremse sind mindestens ausgerüstet mit Hauptleitung, Ausschalthahn, Steuerventil mit bzw. ohne Steuerbehälter, Hilfsluftbehälter und Bremszylinder. Triebfahrzeuge sind zusätzlich ausgerüstet mit Kompressor, Hauptluftbehälter und Führerbremsventil, gegebenenfalls mit Rangier- und Anhängerbremsventil.")
add("6.1.2","Bremsen Hilfsluftbehälter","Wie gelangt die Druckluft beim Bremsen gemäss § in den Bremszylinder?","Vom Hilfsluftbehälter über das Steuerventil, nachdem der Druck in der Hauptleitung abgesenkt wurde.",["Direkt vom Hauptluftbehälter über das Führerbremsventil.","Über die Speiseleitung direkt in den Bremszylinder.","Aus der Hauptleitung direkt in den Bremszylinder."],"Mit dem Führerbremsventil wird der Druck in der Hauptleitung abgesenkt und steuert damit das Steuerventil im einzelnen Fahrzeug in die Bremsstellung und verbindet den Hilfsluftbehälter mit dem Bremszylinder. Die Druckluft strömt vom Hilfsluftbehälter über das Steuerventil in den Raum über dem Kolben des Bremszylinders.")
add("6.2.2","Dreidruckprinzip","Nach welchem Prinzip arbeiten pneumatische Steuerventile gemäss § in der Regel?","Nach dem Dreidruckprinzip.",["Nach dem Zweidruckprinzip.","Nach dem Einkammerprinzip.","Nach dem Vakuumprinzip."],"Pneumatische Steuerventile arbeiten in der Regel nach dem sogenannten Dreidruckprinzip. Gesteuert werden der Hauptleitungsdruck (blau), der Druck im Steuerbehälter (gelb) und der Druck im Bremszylinder (grün).")
addm("6.2.2","Gesteuerte Drücke","Welche Drücke werden beim Dreidruckprinzip gemäss § gesteuert (Mehrfachauswahl).",["Der Hauptleitungsdruck","Der Druck im Steuerbehälter","Der Druck im Bremszylinder"],["Der Druck im Hauptluftbehälter","Der Druck in der Speiseleitung"],"Pneumatische Steuerventile arbeiten in der Regel nach dem sogenannten Dreidruckprinzip. Gesteuert werden der Hauptleitungsdruck (blau), der Druck im Steuerbehälter (gelb) und der Druck im Bremszylinder (grün). Der Druck im Hilfsluftbehälter (rot) enthält den Luftvorrat zur Speisung des Bremszylinders.")
add("6.2.7","Vollständiges Lösen","Wann ist die Bremse gemäss § vollständig gelöst?","Wenn in der Hauptleitung der ursprüngliche Druck wieder erreicht und der Hilfsluftbehälter wieder gefüllt ist.",["Sobald der Bremszylinder entlüftet ist.","Sobald die Fahrstellung eingenommen wurde.","Sobald der Druck 0,2 bar über dem Normaldruck liegt."],"Die Bremse ist erst dann vollständig gelöst, wenn in der Hauptleitung der ursprüngliche d.h. der vor der ersten Bremsung vorhanden gewesene Druck wieder erreicht und der Hilfsluftbehälter wieder gefüllt ist.")
F="Der Höchstdruck im Bremszylinder ist erreicht, wenn der Druck in der Hauptleitung um 1,5 bar vermindert wird. Wurde der Bremszylinder eines Triebfahrzeugs nach einer ersten Bremsung ausgelöst, kann der Bremszylinderdruck mit einer weiteren Senkung des Hauptleitungsdrucks um 0,6 bar noch bis zu einem bestimmten Wert aufgebaut werden. Der Bremszylinder ist vollständig gelöst, sobald der Druck in der Hauptleitung bis auf 0,2 bar unter den Normaldruck angestiegen ist."
add("6.3","Höchstdruck Bremszylinder","Um wie viel muss der Druck in der Hauptleitung vermindert werden, damit der Höchstdruck im Bremszylinder gemäss § erreicht ist?","Um 1,5 bar.",["Um 1 bar.","Um 0,6 bar.","Um 2,5 bar."],F)
add("6.3","Lösegrenze Bremszylinder","Bis auf welchen Wert muss der Druck in der Hauptleitung gemäss § angestiegen sein, damit der Bremszylinder vollständig gelöst ist?","Bis auf 0,2 bar unter den Normaldruck.",["Bis auf den Normaldruck plus 0,2 bar.","Bis auf 0,6 bar unter den Normaldruck.","Bis auf 1,5 bar unter den Normaldruck."],F)
add("6.3","Triebfahrzeug ausgelöste Bremse","Um wie viel kann der Hauptleitungsdruck gemäss § bei einem nach einer ersten Bremsung ausgelösten Triebfahrzeug-Bremszylinder weiter gesenkt werden, um den Bremszylinderdruck noch aufzubauen?","Um weitere 0,6 bar.",["Um weitere 0,2 bar.","Um weitere 1,5 bar.","Um weitere 2,5 bar."],F)
F="Als Durchschlagszeit gilt die Zeit zwischen dem Umlegen des Führerbremsventils in die Schnellbremsstellung und dem Beginn des Druckanstiegs im Bremszylinder des letzten Fahrzeugs. Das Steuerventil ist in der Regel mit einem Beschleunigungsventil ausgerüstet. Dies bewirkt, dass beim Bremsen eine gewisse Menge Druckluft an Ort und Stelle aus der Hauptleitung ausströmt. Dadurch kann die Durchschlagsgeschwindigkeit von ca. 90 bis 180 m/s auf ca. 250 bis 280 m/s erhöht werden."
add("6.4","Durchschlagszeit","Was gilt gemäss § als Durchschlagszeit?","Die Zeit zwischen dem Umlegen des Führerbremsventils in die Schnellbremsstellung und dem Beginn des Druckanstiegs im Bremszylinder des letzten Fahrzeugs.",["Die Zeit bis zum vollständigen Lösen der Bremse.","Die Füllzeit des Hauptluftbehälters.","Die Zeit bis zum Stillstand des Zuges."],F)
add("6.4","Durchschlagsgeschwindigkeit Beschleunigungsventil","Auf welchen Wert kann die Durchschlagsgeschwindigkeit der Druckluftbremse mit einem Beschleunigungsventil gemäss § erhöht werden?","Von ca. 90 bis 180 m/s auf ca. 250 bis 280 m/s.",["Von ca. 15 m/s auf ca. 200 m/s.","Von ca. 30 bis 60 m/s auf ca. 90 bis 180 m/s.","Von ca. 250 bis 280 m/s auf ca. 400 m/s."],F)
F="Die P-Bremse ist eine rasch wirkende Bremse. Sie wird für leichte bis mittelschwere Züge verwendet. Die Bremszylinderfüllzeit beträgt ca. 3 bis 5 s und die Lösezeit ca. 10 bis 20 s."
add("6.6.1","P-Bremse Füllzeit","Wie lange beträgt die Bremszylinderfüllzeit der P-Bremse gemäss § ca.?","Ca. 3 bis 5 s.",["Ca. 18 bis 35 s.","Ca. 10 bis 20 s.","Ca. 45 bis 60 s."],F)
add("6.6.1","P-Bremse Lösezeit","Wie lange beträgt die Lösezeit der P-Bremse gemäss § ca.?","Ca. 10 bis 20 s.",["Ca. 3 bis 5 s.","Ca. 45 bis 60 s.","Ca. 18 bis 35 s."],F)
add("6.6.1","P-Bremse Verwendung","Für welche Züge wird die P-Bremse gemäss § verwendet?","Für leichte bis mittelschwere Züge.",["Für schwere, extrem lange Züge.","Nur für Güterzüge.","Nur für Rangierbewegungen."],F)
F="Die R-Bremse ist grundsätzlich als P-Bremse zu betrachten. Bei Zügen mit höheren Geschwindigkeiten bis zu 160 km/h können die nötigen Bremswege nur eingehalten werden, wenn die Bremsen der Fahrzeuge, welche mit Bremssohlen aus Grauguss ausgerüstet sind, im oberen Geschwindigkeitsbereich verstärkt wirken. Bei Fahrzeugen mit Scheibenbremsen oder Bremssohlen aus Verbundstoff (z.B. K, L und LL) bleibt der Reibungswert über den ganzen Geschwindigkeitsbereich unverändert. Deshalb kann auf eine geschwindigkeitsabhängige R-Bremssteuerung verzichtet werden."
add("6.6.2","R-Bremse Geschwindigkeit","Bei Zügen mit Geschwindigkeiten bis zu welchem Wert kommt gemäss § die R-Bremse zur Anwendung?","Bis zu 160 km/h.",["Bis zu 100 km/h.","Bis zu 120 km/h.","Bis zu 200 km/h."],F)
add("6.6.2","R-Bremse Grauguss","Was ist bei Fahrzeugen mit Bremssohlen aus Grauguss gemäss § erforderlich, damit bei höheren Geschwindigkeiten die nötigen Bremswege eingehalten werden?","Die Bremsen müssen im oberen Geschwindigkeitsbereich verstärkt wirken.",["Die Bremsen müssen im oberen Geschwindigkeitsbereich schwächer wirken.","Die Bremsen müssen langsamer ansprechen.","Die Bremsen müssen ausgeschaltet werden."],F)
add("6.6.2","R-Bremse Verbundstoff","Weshalb kann bei Fahrzeugen mit Scheibenbremsen oder Verbundstoffsohlen gemäss § auf eine geschwindigkeitsabhängige R-Bremssteuerung verzichtet werden?","Der Reibungswert bleibt über den ganzen Geschwindigkeitsbereich unverändert.",["Der Reibungswert nimmt stark ab.","Die Bremse wirkt langsamer.","Die Haftreibung ist grösser."],F)
F="Die G-Bremse ist eine langsam wirkende Bremse. Sie hat deshalb längere Bremswege zur Folge. Sie wird für schwere, aus nicht einheitlichem Wagenmaterial bestehenden oder für extrem lange Züge verwendet. Die Bremszylinderfüllzeit beträgt in Abhängigkeit der Zuglänge ca. 18 bis 35 s und die Lösezeit ca. 45 bis 60 s. Der für die G-Bremse vorgeschriebene rasche Ansprung der Bremskraft (Einschuss) bei Beginn der Bremsung wird im Steuerventil mit dem sogenannten Mindestdruckventil erzeugt. Dieses lässt Druckluft vom Hilfsluftbehälter direkt in den Bremszylinder einströmen, bis darin ein Druck von 0,8 bar erreicht ist."
add("6.7","G-Bremse Füllzeit","Wie lange beträgt die Bremszylinderfüllzeit der G-Bremse gemäss § in Abhängigkeit der Zuglänge ca.?","Ca. 18 bis 35 s.",["Ca. 3 bis 5 s.","Ca. 10 bis 20 s.","Ca. 45 bis 60 s."],F)
add("6.7","G-Bremse Lösezeit","Wie lange beträgt die Lösezeit der G-Bremse gemäss § ca.?","Ca. 45 bis 60 s.",["Ca. 10 bis 20 s.","Ca. 18 bis 35 s.","Ca. 3 bis 5 s."],F)
add("6.7","G-Bremse Verwendung","Für welche Züge wird die G-Bremse gemäss § verwendet?","Für schwere, aus nicht einheitlichem Wagenmaterial bestehende oder extrem lange Züge.",["Für leichte Reisezüge.","Nur für Triebzüge.","Für Züge mit Scheibenbremsen."],F)
add("6.7","Mindestdruckventil","Welcher Druck wird im Bremszylinder gemäss § beim Einschuss der G-Bremse durch das Mindestdruckventil erreicht?","0,8 bar.",["0,2 bar.","1,5 bar.","0,4 bar."],F)
add("6.7","G-Bremse Längsdruckkräfte","Weshalb wird die Bremskraft bei der G-Bremse gemäss § nach dem Einschuss verhältnismässig langsam aufgebaut?","Damit zu hohe Längsdruckkräfte im Zug vermieden werden.",["Damit die Bremszylinder weniger Druckluft verbrauchen.","Damit der Bremsweg kürzer wird.","Damit die Bremsen früher lösen."],F)
add("6.7","Ungewollte Längsdruckkräfte","Wozu können ungewollte Längsdruckkräfte bei Güterzügen gemäss § bei nicht sachgerechter Bremsbedienung führen?","Zu Pufferübergreifungen und Entgleisungen.",["Zu einem Ausfall des Kompressors.","Zu einer Überladung der Hauptleitung.","Zu einem Einfrieren der Bremssohlen."],"Das nicht einheitliche Wagenmaterial und die unterschiedlichen Beladungszustände bewirken auch eine unterschiedliche Abbremsung der einzelnen Fahrzeuge und dadurch das Entstehen ungewollter Längsdruckkräfte, die bei nicht sachgerechter Bremsbedienung zu Pufferübergreifungen und Entgleisungen führen können.")
F="Mit dem Führerbremsventil kann der Druck in der Hauptleitung reguliert werden. Die Füllstellung (Querschnittswechsel) dient dem raschen Füllen der Hauptleitung und der Bremsapparate. Bei vielen Führerbremsventiltypen bewirkt das Verbringen in die Füllstellung einen zeitlich begrenzten Füllstoss (Druckwelle) mit anschliessender Niederdrucküberladung (Angleichfunktion) der Hauptleitung auf 0,2 bis 0,4 bar über dem Normaldruck. In der Fahrstellung wird diese Verbindung gedrosselt. Die Niederdrucküberladung baut sich dadurch langsam ab, so dass die Bremsen nicht ansprechen. In der Neutralstellung bzw. Abschlussstellung ist die Verbindung zwischen Hauptluftbehälter und Hauptleitung unterbrochen."
add("6.9","Füllstellung Zweck","Wozu dient die Füllstellung (Querschnittswechsel) des Führerbremsventils gemäss §?","Dem raschen Füllen der Hauptleitung und der Bremsapparate.",["Dem Abbau der Niederdrucküberladung.","Dem stufenweisen Bremsen.","Dem Unterbrechen der Verbindung zwischen Hauptluftbehälter und Hauptleitung."],F)
add("6.9","Niederdrucküberladung","Auf welchen Wert wird die Hauptleitung bei der Niederdrucküberladung (Angleichfunktion) gemäss § über dem Normaldruck eingestellt?","Auf 0,2 bis 0,4 bar über dem Normaldruck.",["Auf 0,5 bis 0,8 bar über dem Normaldruck.","Auf 1 bis 1,5 bar über dem Normaldruck.","Auf 0,2 bis 0,4 bar unter dem Normaldruck."],F)
add("6.9","Fahrstellung","Was bewirkt die Fahrstellung des Führerbremsventils gemäss § bei der Niederdrucküberladung?","Die Verbindung wird gedrosselt und die Niederdrucküberladung baut sich langsam ab, sodass die Bremsen nicht ansprechen.",["Die Hauptleitung wird entlüftet.","Die Niederdrucküberladung wird verstärkt.","Die Bremsen sprechen an."],F)
add("6.9","Neutralstellung","Was gilt gemäss § in der Neutral- bzw. Abschlussstellung des Führerbremsventils?","Die Verbindung zwischen Hauptluftbehälter und Hauptleitung ist unterbrochen.",["Die Hauptleitung wird direkt ins Freie entlüftet.","Der Hauptluftbehälter ist direkt mit der Hauptleitung verbunden.","Die Hauptleitung wird mit Normaldruck gespeist."],F)
F="Die Fahrzeuge sind mit einem Auslöseventil ausgerüstet. Mit diesem kann durch Entleerung der Bremsapparate die Bremse ohne Erhöhung des Hauptleitungsdrucks gelöst werden. Bei Triebfahrzeugen kann das Auslöseventil an der Pneumatiktafel, bei Wagen in der Regel mit Zugstangen oder -drähten von beiden Seiten aus betätigt werden."
add("6.10","Auslöseventil","Was ermöglicht das Auslöseventil gemäss §?","Das Lösen der Bremse durch Entleerung der Bremsapparate ohne Erhöhung des Hauptleitungsdrucks.",["Das Lösen der Bremse durch Erhöhung des Hauptleitungsdrucks.","Das Ausschalten der Bremse am Wagen.","Das rasche Füllen der Hauptleitung."],F)
add("6.10","Auslöseventil Betätigung Wagen","Wie wird das Auslöseventil bei Wagen gemäss § in der Regel betätigt?","Mit Zugstangen oder -drähten von beiden Seiten aus.",["An der Pneumatiktafel.","Nur vom Führerstand aus.","Nur von einer Seite aus."],F)
F="Die EP-Bremse ist eine elektropneumatisch gesteuerte automatische Druckluftbremse. Die EP-Bremse ermöglicht das gleichzeitige Bremsen oder Lösen aller Fahrzeuge unabhängig von der Länge des Zuges. Damit kann eine gleichmässige Bremsung mit geringsten Längsdruckkräften im Zug erreicht werden. Fällt die elektropneumatische Steuerung aus, wird die Bremse rein pneumatisch über die Hauptleitung gesteuert."
add("6.11","EP-Bremse Vorteil","Was ermöglicht die EP-Bremse gemäss §?","Das gleichzeitige Bremsen oder Lösen aller Fahrzeuge unabhängig von der Länge des Zuges.",["Das Bremsen ohne Druckluft.","Ein Bremsen unabhängig von der Haftreibung.","Das Bremsen nur der Triebfahrzeuge."],F)
add("6.11","EP-Bremse Ausfall","Was geschieht gemäss § bei Ausfall der elektropneumatischen Steuerung?","Die Bremse wird rein pneumatisch über die Hauptleitung gesteuert.",["Die Bremse wird ausgeschaltet.","Es erfolgt eine Zwangsbremsung.","Die Bremse wird rein elektrisch gesteuert."],F)
add("6.11.1","Direkt wirkende EP-Bremse","Wodurch wird der Druck in den Bremszylindern bei der direkt wirkenden EP-Bremse gemäss § reguliert?","Durch ein elektropneumatisches Ventil auf jedem Fahrzeug in Abhängigkeit des Befehls in der EP-Leitung.",["Durch das Steuerventil in Abhängigkeit vom Hauptleitungsdruck.","Durch das Führerbremsventil direkt über die Hauptleitung.","Durch einen Druckregler am Triebfahrzeug."],"Bei der direkt wirkenden EP-Bremse ist ein Steuergerät auf dem Triebfahrzeug oder Steuerwagen mit dem Führerbremsventil oder dem massgebenden Bedienelement kombiniert. Das Steuergerät gibt einen Brems- oder Lösebefehl ab, der proportional zur gewünschten Bremswirkung ist. Auf jedem Fahrzeug im Zug ist ein elektropneumatisches Ventil vorhanden, das in Abhängigkeit des Befehls in der elektrischen Steuerleitung (EP-Leitung) den Druck in den Bremszylindern entsprechend reguliert.")
add("6.11.2","Indirekt wirkende EP-Bremse","Wann gibt das Steuergerät bei der indirekt wirkenden EP-Bremse gemäss § einen elektrischen Brems- oder Lösebefehl ab?","Wenn der Druck in der Hauptleitung gesenkt oder erhöht wird.",["Wenn die EP-Leitung unterbrochen wird.","Wenn die Speiseleitung entleert wird.","Wenn die Rangierbremse betätigt wird."],"Bei der indirekt wirkenden EP-Bremse wird das Steuergerät auf dem Triebfahrzeug oder Steuerwagen mit dem Führerbremsventil betätigt. Es gibt einen elektrischen Brems- oder Lösebefehl ab, wenn der Druck in der Hauptleitung gesenkt oder erhöht wird. Jedes Fahrzeug besitzt zwei Elektroventile: ein Bremsventil und ein Löseventil.")
F="Die Bremse ist betriebsbereit bzw. gelöst, wenn zwischen dem atmosphärischen Druck und dem System eine Druckdifferenz von 52 cmHg erzeugt ist und zwischen Unter- und Oberkammern der angeschlossenen Bremszylinder Druckausgleich herrscht."
add("7.1.1","Vakuum Betriebsbereit","Welche Druckdifferenz zwischen atmosphärischem Druck und System muss bei der Vakuumbremse gemäss § erzeugt sein, damit die Bremse betriebsbereit ist?","52 cmHg.",["42 cmHg.","20 cmHg.","76 cmHg."],F)
add("7.2","Vakuum Durchschlag","Wie gross ist die Durchschlagsgeschwindigkeit bei der Vakuumbremse gemäss § in der Regel und bei einer Schnellbremsung?","In der Regel 15 m/s, bei einer Schnellbremsung ca. 200 m/s.",["In der Regel 90 m/s, bei einer Schnellbremsung ca. 250 m/s.","In der Regel 200 m/s, bei einer Schnellbremsung ca. 15 m/s.","In der Regel 15 m/s, bei einer Schnellbremsung ca. 30 m/s."],"Die Durchschlagsgeschwindigkeit beträgt in der Regel 15 m/s, bei einer Schnellbremsung ca. 200 m/s.")
add("7.3","Vakuumgesteuerte Druckluftbremse Mindestdruck","Bei welchem Druck der Speiseleitung wird die Hauptleitung bei der vakuumgesteuerten Druckluftbremse gemäss § zwangsbelüftet?","Wenn der Druck unter 5,5 bar sinkt.",["Wenn der Druck unter 3 bar sinkt.","Wenn der Druck unter 7 bar sinkt.","Wenn der Druck 52 cmHg erreicht."],"Mit der Mindestdrucküberwachung 10 wird der Druck der Speiseleitung überwacht. Sinkt dieser unter 5,5 bar, wird die Hauptleitung zwangsbelüftet.")
add("8","Rangierbremse Definition","Wie wird die auf dem Triebfahrzeug oder Steuerwagen vorhandene direkt wirkende Luftbremse gemäss § bezeichnet?","Als Rangierbremse.",["Als automatische Bremse.","Als Nachbremse.","Als Schleuderbremse."],"Die auf dem Triebfahrzeug oder Steuerwagen vorhandene direkt wirkende Luftbremse wird als Rangierbremse bezeichnet. Sie wirkt auf das Triebfahrzeug bzw. auf den Steuerwagen und gegebenenfalls auf weitere Triebfahrzeuge in Vielfachsteuerung.")
add("8","Rangierbremse regulieren","Wie kann der Druck im Bremszylinder bei der Rangierbremse gemäss § reguliert werden?","Beim Bremsen wie auch beim Lösen kontinuierlich.",["Nur beim Bremsen.","Nur stufenweise beim Lösen.","Nur durch Schnellbremsung."],"Mit der Rangierbremse kann beim Bremsen wie auch beim Lösen der Druck im Bremszylinder kontinuierlich reguliert werden.")
add("9","Schienenbremse Verwendung","Wozu wird die Schienenbremse gemäss § ausser zur Verkürzung des Bremswegs bei Schnellbremsung und als Feststellbremse verwendet?","Als Kompensation der Bremskraft bei plötzlichem Ausfall der elektrischen Bremse.",["Als Kompensation bei Ausfall des Kompressors.","Zum Lösen der Federspeicherbremse.","Zur Erhöhung der Haftreibung zwischen Rad und Schiene."],"Schienenbremsen werden verwendet zur Verkürzung des Bremswegs beim Einleiten einer Schnellbremsung, als Kompensation der Bremskraft bei plötzlichem Ausfall der elektrischen Bremse und als Feststellbremse.")
add("9","Schienenbremse Reibung","Wovon ist die Reibungskraft der Schienenbremse gemäss § unabhängig?","Von der Rad/Schiene-Reibung.",["Von der Magnetkraft.","Vom Schienenkopf.","Von der Bremsschuhe."],"Die Bremsschuhe üben ihre Bremskraft in der Regel durch elektro- oder permanentmagnetische Kraftwirkung auf den Schienenkopf aus. Dadurch wird die Reibungskraft unabhängig von der Rad/Schiene-Reibung unmittelbar auf die Schiene ausgeübt.")
F="Die Notbremseinrichtung bezweckt, dass im Notfall ein Zug oder eine Rangierbewegung angehalten werden kann. Eine Notbremseinrichtung befindet sich in der Regel auf jedem Fahrzeug, auf dem sich während der Fahrt Personen aufhalten können."
add("10","Notbremseinrichtung","Wo befindet sich eine Notbremseinrichtung gemäss § in der Regel?","Auf jedem Fahrzeug, auf dem sich während der Fahrt Personen aufhalten können.",["Nur auf den Triebfahrzeugen.","Nur auf Güterwagen.","Nur auf dem letzten Fahrzeug."],F)
F="Jedes dem Reisenden zugängliche Fahrzeug ist in der Regel mit einem Notbremsventil ausgerüstet. Das geöffnete Notbremsventil verbindet die Hauptleitung unmittelbar mit dem Freien und es tritt eine Notbremsung ein, wobei bei vielen Wagen durch das Ausströmen der Druckluft gleichzeitig eine Signalpfeife aktiviert wird. Der normale Betriebszustand kann in der Regel nur mit einer besonderen Rückstellvorrichtung oder mit Hilfe des Wagenschlüssels hergestellt werden. Dienst-, Gepäck- und Güterwagen können mit einem einfachen Notbremshahn ohne Rückstellvorrichtung ausgerüstet sein."
add("10.1","Notbremsventil","Was geschieht gemäss § beim geöffneten Notbremsventil?","Die Hauptleitung wird unmittelbar mit dem Freien verbunden und es tritt eine Notbremsung ein.",["Die Hauptleitung wird mit der Speiseleitung verbunden.","Der Hilfsluftbehälter wird entleert.","Die Bremsen werden gelöst."],F)
add("10.1","Notbremsventil Rückstellung","Wie kann der normale Betriebszustand nach dem Öffnen des Notbremsventils gemäss § in der Regel hergestellt werden?","Nur mit einer besonderen Rückstellvorrichtung oder mit Hilfe des Wagenschlüssels.",["Durch einfaches Zurückdrehen des Griffs von Hand.","Nur vom Führerstand aus.","Durch Betätigen des Auslöseventils."],F)
add("10.2.1","Notbremsüberbrückung","Was gilt gemäss § bei der Notbremsüberbrückung?","Die Wirkung der Notbremsung kann durch den LF im Führerstand überbrückt werden; ein anderweitig bedingter Luftverlust (z.B. Zugtrennung) kann nicht überbrückt werden.",["Jeder Luftverlust in der Hauptleitung kann überbrückt werden.","Die Notbremsung kann nur vom Reisenden aufgehoben werden.","Eine betätigte Notbremseinrichtung löst keine Notbremsung aus."],"Ein geöffnetes Notbremsventil löst eine Notbremsung aus, gleichzeitig wird im Führerstand die Betätigung der Notbremse angezeigt. Die Wirkung der Notbremsung kann durch den LF im Führerstand überbrückt werden. Ein anderweitig bedingter Luftverlust in der Hauptleitung (z.B. Zugtrennung) kann nicht überbrückt werden.")
add("10.2.2","Notbremsanforderung","Was geschieht gemäss § bei einer betätigten Notbremseinrichtung mit Notbremsanforderung?","Sie wird im Führerstand angezeigt, löst jedoch keine Notbremsung aus.",["Sie löst sofort eine Notbremsung aus.","Sie löst eine Zwangsbremsung aus.","Sie wird nicht angezeigt."],"Eine betätigte Notbremseinrichtung wird im Führerstand angezeigt, löst jedoch keine Notbremsung aus.")
add("10.2","Notbremsüberbrückung Zweck","Was soll die Notbremsüberbrückung bzw. -anforderung gemäss § verhindern?","Dass ein Zug an ungeeigneter Stelle zum Stillstand kommt.",["Dass die Hauptleitung entleert wird.","Dass Reisende die Notbremse missbrauchen.","Dass die Bremsen einfrieren."],"Fahrzeuge für Personenbeförderung sind in bestimmten Fällen mit einer Notbremsüberbrückung oder einer Notbremsanforderung ausgerüstet. Die Notbremsüberbrückung bzw. -anforderung soll verhindern, dass ein Zug an ungeeigneter Stelle zum Stillstand kommt.")
add("11","Schnellbremsbeschleuniger","Welche Wirkung haben die Schnellbremsbeschleunigungsorgane gemäss § bei einer Schnell- oder Notbremsung?","Sie verbinden die Hauptleitung mit dem Freien und erhöhen dadurch die Durchschlagsgeschwindigkeit wesentlich.",["Sie unterbrechen die Nachspeisung.","Sie lösen die Bremsen nach kurzer Zeit.","Sie verringern die Durchschlagsgeschwindigkeit."],"Bei einer raschen Entleerung der Hauptleitung (Schnell- oder Notbremsung) verbinden die Schnellbremsbeschleunigungsorgane an den Fahrzeugen die Hauptleitung mit dem Freien. Dadurch kann die Durchschlagsgeschwindigkeit wesentlich erhöht werden. Nach dem Ansprechen der Schnellbremsbeschleunigungsorgane schliessen diese die Verbindung zwischen Hauptleitung und dem Freien erst wieder, nachdem die Hauptleitung komplett entleert wurde.")
add("12","Anhängerbremse","Was ermöglicht die Anhängerbremse gemäss §?","Das Bedienen der automatischen Bremse der Anhängelast mit der Rangierbremse des Triebfahrzeuges.",["Das Bedienen der Rangierbremse vom Wagen aus.","Das Lösen der Federspeicherbremse.","Das Bedienen der elektrischen Bremse vom Boden aus."],"Die Anhängerbremse ermöglicht das Bedienen der automatischen Bremse der Anhängelast mit der Rangierbremse des Triebfahrzeuges.")
F="Traktoren ohne automatische Bremse oder Triebfahrzeuge, deren automatische Bremse beim Schleppen nicht wirksam ist, sind mit einer Nachbremse ausgerüstet. Bei einer Betriebs- oder Vollbremsung sowie bei der Bedienung der Anhängerbremse spricht die Nachbremse nicht an. Die Nachbremse bewirkt, dass die Luftbremse eines an die Hauptleitung angeschlossenen Triebfahrzeugs zum Ansprechen kommt, wenn der Hauptleitungsdruck um ca. 2,5 bar abgesenkt wird."
add("13.1","Nachbremse Ansprechen","Bei welcher Absenkung des Hauptleitungsdrucks kommt die Nachbremse gemäss § zum Ansprechen?","Bei ca. 2,5 bar.",["Bei ca. 0,5 bar.","Bei ca. 1,5 bar.","Bei ca. 1 bar."],F)
add("13.1","Nachbremse Ausrüstung","Womit sind Triebfahrzeuge, deren automatische Bremse beim Schleppen nicht wirksam ist, gemäss § ausgerüstet?","Mit einer Nachbremse.",["Mit einer Schleuderbremse.","Mit einer Anhängerbremse.","Mit einer Federspeicherbremse."],F)
add("13.1","Nachbremse Betriebsbremsung","Wann spricht die Nachbremse gemäss § nicht an?","Bei einer Betriebs- oder Vollbremsung sowie bei der Bedienung der Anhängerbremse.",["Bei einer Schnellbremsung.","Bei einer Notbremsung.","Bei einer Zwangsbremsung."],F)
add("14","Schleuderbremse","Was verhindert die Schleuderbremse gemäss §?","Durch leichtes Anbremsen das Schleudern der Triebräder bei schlechten Adhäsionsverhältnissen.",["Das Blockieren der Räder beim Bremsen.","Das Entlaufen abgestellter Fahrzeuge.","Das Überladen der Hauptleitung."],"Die Schleuderbremse verhindert durch leichtes Anbremsen das Schleudern der Triebräder bei schlechten Adhäsionsverhältnissen.")
F="Die Bremskraft kann in ungünstigen Fällen den Grenzwert der Haftung zwischen Rad und Schiene erreichen. Dabei besteht die Gefahr, dass die Achsen beim Bremsen blockieren. Das führt zu längeren Bremswegen und hat weiter zur Folge, dass die Laufflächen der Räder durch Flachstellen beschädigt werden. Die Gleitschutzvorrichtung vergleicht die Drehzahl der Fahrzeugachsen. Sobald die Drehzahldifferenz einen bestimmten Wert erreicht, wird der Bremszylinder entlüftet und dessen Speisung unterbrochen."
add("15","Gleitschutz Funktion","Was geschieht gemäss § bei der Gleitschutzvorrichtung, sobald die Drehzahldifferenz der Fahrzeugachsen einen bestimmten Wert erreicht?","Der Bremszylinder wird entlüftet und dessen Speisung unterbrochen.",["Die Bremse wird verstärkt.","Die Hauptleitung wird entleert.","Der Bremszylinder wird zusätzlich gefüllt."],F)
addm("15","Folgen Blockieren","Welche Folgen hat das Blockieren der Achsen beim Bremsen gemäss § (Mehrfachauswahl).",["Längere Bremswege","Beschädigung der Laufflächen der Räder durch Flachstellen"],["Kürzere Bremswege","Höherer Haftreibungswert"],F)
add("16","Bremsrechner Schnellbremsung","Wie kann eine Schnellbremsung bei Fahrzeugen mit Bremsrechner gemäss § in jedem Fall ausgeführt werden?","Direkt durch Öffnen der Hauptleitung mit einem Nothahn oder einem Notbremsventil unter Umgehung des Rechners.",["Nur über den Datenbus und das Fahrzeugleitgerät.","Nur mit dem Rechner.","Nur mit der Rangierbremse."],"Eine Schnellbremsung kann in jedem Fall direkt durch Öffnen der Hauptleitung mit einem Nothahn oder einem Notbremsventil unter Umgehung des Rechners ausgeführt werden.")
F="Die Sicherheitsbremse ist von der Reibung zwischen Rad und Schiene unabhängig. Als Sicherheitsbremsen gelten unter anderem Schienen- und Zahnradbremsen. Sicherheitsbremsen werden verwendet zum Befahren von Strecken, die mehr als 60 ‰ Neigung aufweisen."
add("17","Sicherheitsbremse Definition","Wovon ist die Sicherheitsbremse gemäss § unabhängig?","Von der Reibung zwischen Rad und Schiene.",["Von der Zugkraft des Triebfahrzeugs.","Von der Hauptleitung.","Von der Geschwindigkeit."],F)
add("17","Sicherheitsbremse Neigung","Ab welcher Neigung werden Sicherheitsbremsen gemäss § zum Befahren von Strecken verwendet?","Bei mehr als 60 ‰ Neigung.",["Bei mehr als 25 ‰ Neigung.","Bei mehr als 40 ‰ Neigung.","Bei mehr als 100 ‰ Neigung."],F)
add("17","Sicherheitsbremse Arten","Welche Bremsen gelten gemäss § unter anderem als Sicherheitsbremsen?","Schienen- und Zahnradbremsen.",["Klotz- und Scheibenbremsen.","Rangier- und Anhängerbremsen.","Nutzstrom- und Widerstandsbremsen."],F)
F="Federspeicherbremsen werden verwendet als Feststellbremse und in bestimmten Fällen als Systemteil der automatischen Bremse. Bei der Federspeicherbremse wirkt die Bremskraft durch eine im Bremszylinder angebrachte Feder direkt auf dessen Kolbenstange. Fehlt die zum Lösen nötige Kraft, kann die Federspeicherbremse nur mit einer speziellen Einrichtung gelöst werden. Nach dem Notlösen ist die Federspeicherbremse unwirksam."
add("18.1","Federspeicherbremse Wirkung","Wodurch wird die Bremskraft bei der Federspeicherbremse gemäss § erzeugt?","Durch eine im Bremszylinder angebrachte Feder, die direkt auf die Kolbenstange wirkt.",["Durch Druckluft im Bremszylinder.","Durch Magnetkraft auf den Schienenkopf.","Durch die Triebmotoren als Generatoren."],F)
add("18.2","Notlösen","Was gilt gemäss § nach dem Notlösen der Federspeicherbremse?","Die Federspeicherbremse ist unwirksam.",["Die Federspeicherbremse wirkt mit halber Kraft.","Die Federspeicherbremse wirkt automatisch wieder.","Die Federspeicherbremse bleibt voll wirksam."],F)
add("18","Federspeicherbremse Verwendung","Wofür werden Federspeicherbremsen gemäss § verwendet?","Als Feststellbremse und in bestimmten Fällen als Systemteil der automatischen Bremse.",["Nur als Rangierbremse.","Nur als Sicherheitsbremse bei Neigungen über 60 ‰.","Nur als Notbremse."],F)
run(seed=2149,new_reg=('r14','R 300.14','R 300.14 BREMSEN'))
